"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { Database, FileText, Activity, ArrowLeft } from "lucide-react";
import CreateEntityModal from "@/components/plugins/CreateEntityModal";
import CRMLeadsView from "@/components/plugins/CRMLeadsView";
import FinanceInvoicesView from "@/components/plugins/FinanceInvoicesView";
import HRLeaveRequestsView from "@/components/plugins/HRLeaveRequestsView";
import { useThemeStore } from "@/store/useThemeStore";
import { fetchWithAuth, API_BASE_URL } from "@/lib/apiClient";

export default function PluginsPage() {
  const [activePlugin, setActivePlugin] = useState<"lead" | "invoice" | "leave_request">("lead");
  const [entities, setEntities] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const { primaryColor } = useThemeStore();

  const pluginTypes = [
    { id: "lead", label: "CRM: Leads", icon: Database },
    { id: "invoice", label: "Finance: Invoices", icon: FileText },
    { id: "leave_request", label: "HR: Leave Requests", icon: Activity },
  ];

  const fetchEntities = React.useCallback(async (type: string, signal?: AbortSignal) => {
    setTimeout(() => {
      if (!signal?.aborted) setLoading(true);
    }, 0);
    try {
      const workspaceId = localStorage.getItem("currentWorkspaceId") || "797ec9d1-e70e-4ca7-a9aa-2d4fed3d879e";

      const res = await fetchWithAuth(`${API_BASE_URL}/entities?workspace_id=${workspaceId}&type=${type}`, {
        signal
      });
      if (res.ok) {
        const data = await res.json();
        if (!signal?.aborted) setEntities(data.data || []);
      }
    } catch (err: unknown) {
      const error = err as { name?: string };
      if (error?.name !== 'AbortError' && !signal?.aborted) {
        console.error("Failed to fetch entities:", error);
        setEntities([]);
      }
    } finally {
      if (!signal?.aborted) setLoading(false);
    }
  }, []);

  useEffect(() => {
    const abortController = new AbortController();
    // eslint-disable-next-line
    void fetchEntities(activePlugin, abortController.signal);
    return () => abortController.abort();
  }, [activePlugin, fetchEntities]);

  return (
    <div className="flex h-screen overflow-hidden bg-white text-slate-900">
      {/* Sidebar for Plugins */}
      <div className="w-64 border-r border-black/10 p-4 shrink-0 bg-[var(--sb-bg)] text-[var(--sb-text)] flex flex-col">
        <h2 className="text-xl font-bold mb-6">Enterprise Plugins</h2>
        <nav className="space-y-2 flex-1">
          {pluginTypes.map((plugin) => {
            const Icon = plugin.icon;
            const isActive = activePlugin === plugin.id;
            return (
              <button
                key={plugin.id}
                onClick={() => setActivePlugin(plugin.id as "lead" | "invoice" | "leave_request")}
                className={`w-full flex items-center p-3 rounded-lg transition-colors ${
                  isActive ? "text-[var(--sb-text)] font-semibold" : "opacity-80 hover:bg-[var(--sb-hover)]"
                }`}
                style={{ backgroundColor: isActive ? primaryColor : "transparent" }}
              >
                <Icon className="w-5 h-5 mr-3" />
                {plugin.label}
              </button>
            );
          })}
        </nav>

        <div className="mt-4 pt-4 border-t border-black/10">
          <Link 
            href="/"
            className="w-full flex items-center p-3 rounded-lg transition-colors opacity-80 hover:bg-[var(--sb-hover)] hover:opacity-100"
          >
            <ArrowLeft className="w-5 h-5 mr-3" />
            Back to Home
          </Link>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-8 overflow-y-auto min-w-0">
        {activePlugin === "lead" && (
          <CRMLeadsView 
            entities={entities as any} 
            loading={loading} 
            onNewLead={() => setIsModalOpen(true)} 
            onRefresh={() => fetchEntities(activePlugin)}
          />
        )}

        {activePlugin === "invoice" && (
          <FinanceInvoicesView 
            entities={entities as any} 
            loading={loading} 
            onNewInvoice={() => setIsModalOpen(true)} 
            onRefresh={() => fetchEntities(activePlugin)}
          />
        )}

        {activePlugin === "leave_request" && (
          <HRLeaveRequestsView 
            entities={entities as any} 
            loading={loading} 
            onNewRequest={() => setIsModalOpen(true)} 
            onRefresh={() => fetchEntities(activePlugin)}
          />
        )}
      </div>

      {isModalOpen && (
        <CreateEntityModal 
          pluginType={activePlugin} 
          onClose={() => setIsModalOpen(false)} 
          onSuccess={() => fetchEntities(activePlugin)} 
        />
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Users, Shield, Building2, Search, Plus } from "lucide-react";
import { apiGet, apiPut, apiPost } from "@/lib/apiClient";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import PermissionsMatrix from "./PermissionsMatrix";
import OrgChartContainer from "../org/OrgChartContainer";

interface User {
  ID: string;
  Name: string;
  Email: string;
  RoleID: string | null;
  Role?: { Name: string };
  DepartmentID: string | null;
  Department?: { Name: string };
}

export default function AdminDashboard() {
  const [users, setUsers] = useState<User[]>([]);
  const [departments, setDepartments] = useState<{ID: string, Name: string}[]>([]);
  const [roles, setRoles] = useState<{ID: string, Name: string}[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("users"); // users, roles, departments
  const [searchQuery, setSearchQuery] = useState("");
  const [newDeptName, setNewDeptName] = useState("");
  const [isAddDeptOpen, setIsAddDeptOpen] = useState(false);

  const filteredUsers = users.filter(user => 
    (user.Name && user.Name.toLowerCase().includes(searchQuery.toLowerCase())) || 
    (user.Email && user.Email.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const fetchAllData = async () => {
    try {
      const [usersData, deptsData, rolesData] = await Promise.all([
        apiGet<any>("/admin/users"),
        apiGet<any>("/admin/departments"),
        apiGet<any>("/admin/roles")
      ]);

      setUsers(Array.isArray(usersData) ? usersData : usersData.users || []);
      setDepartments(Array.isArray(deptsData) ? deptsData : []);
      setRoles(Array.isArray(rolesData) ? rolesData : []);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const loadData = async () => {
      await fetchAllData();
    };
    loadData();
  }, []);

  const handleUpdateUser = async (e: React.FormEvent, userId: string) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const data = {
      name: (form.elements.namedItem("name") as HTMLInputElement).value,
      email: (form.elements.namedItem("email") as HTMLInputElement).value,
      department_id: (form.elements.namedItem("department") as HTMLSelectElement).value || null,
      role_id: (form.elements.namedItem("role") as HTMLSelectElement).value || null,
    };

    try {
      await apiPut(`/admin/users/${userId}`, data);
      fetchAllData();
      alert("تم تحديث المستخدم بنجاح");
    } catch (error) {
      console.error(error);
      alert("حدث خطأ أثناء التحديث");
    }
  };

  const handleAddDepartment = async () => {
    if (!newDeptName) return;
    try {
      await apiPost("/admin/departments", { Name: newDeptName });
      setNewDeptName("");
      setIsAddDeptOpen(false);
      fetchAllData();
      alert("تمت إضافة القسم بنجاح");
    } catch (error) {
      console.error(error);
      alert("حدث خطأ أثناء الإضافة");
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#f8fafc]">
      {/* Header */}
      <div className="flex-none p-8 pb-4 border-b border-slate-200 bg-white">
        <h1 className="text-2xl font-bold text-slate-800">لوحة تحكم المسؤول (Admin)</h1>
        <p className="text-slate-500 mt-1">إدارة المستخدمين، الصلاحيات، والهيكل التنظيمي للمؤسسة</p>

        {/* Tabs */}
        <div className="flex gap-4 mt-6">
          <TabButton 
            active={activeTab === "users"} 
            onClick={() => setActiveTab("users")} 
            icon={<Users size={18} />} 
            label="المستخدمين" 
          />
          <TabButton 
            active={activeTab === "roles"} 
            onClick={() => setActiveTab("roles")} 
            icon={<Shield size={18} />} 
            label="الأدوار والصلاحيات" 
          />
          <TabButton 
            active={activeTab === "departments"} 
            onClick={() => setActiveTab("departments")} 
            icon={<Building2 size={18} />} 
            label="الأقسام (Org Chart)" 
          />
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-8">
        {activeTab === "users" && (
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm">
            <div className="p-6 border-b border-slate-200 flex justify-between items-center">
              <div className="relative">
                <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                <input 
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="البحث عن مستخدم..." 
                  className="pl-4 pr-10 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-brand w-64"
                />
              </div>
              <div className="flex gap-2">
                <Dialog open={isAddDeptOpen} onOpenChange={setIsAddDeptOpen}>
                  <DialogTrigger className="bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center gap-2 h-10 px-4 py-2 rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50">
                    <Building2 size={16} />
                    إضافة قسم
                  </DialogTrigger>
                  <DialogContent className="sm:max-w-[425px]" dir="rtl">
                    <DialogHeader>
                      <DialogTitle>إضافة قسم جديد</DialogTitle>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                      <div className="grid grid-cols-4 items-center gap-4">
                        <label className="text-right text-sm font-medium">اسم القسم</label>
                        <input title="اسم القسم" aria-label="اسم القسم" value={newDeptName} onChange={e => setNewDeptName(e.target.value)} className="col-span-3 flex h-10 w-full rounded-md border border-slate-300 bg-transparent px-3 py-2 text-sm" placeholder="مثال: التسويق" />
                      </div>
                    </div>
                    <DialogFooter>
                      <Button onClick={handleAddDepartment} className="bg-brand hover:bg-brand text-white w-full">حفظ القسم</Button>
                    </DialogFooter>
                  </DialogContent>
                </Dialog>

                <Dialog>
