import React, { useState, useEffect } from "react";
import { Check, X, Shield, Save } from "lucide-react";
import { Button } from "@/components/ui/button";
import { fetchWithAuth,     API_BASE_URL } from '@/lib/apiClient';

interface Permission {
  ID: string;
  Module: string;
  Name: string; // The action name basically
}

interface Role {
  ID: string;
  Name: string;
  Description: string;
}

interface RolePermission {
  RoleID: string;
  PermissionID: string;
}

interface MatrixRole {
  id: string;
  name: string;
  permissions: string[];
}

interface MatrixPermission {
  id: string;
  module: string;
  action: string;
}

export default function PermissionsMatrix() {
  const [roles, setRoles] = useState<MatrixRole[]>([]);
  const [permissions, setPermissions] = useState<MatrixPermission[]>([]);
  const [originalRolePerms, setOriginalRolePerms] = useState<RolePermission[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  const fetchData = async () => {
    try {
      const headers = { "Content-Type": "application/json" };

      const [rolesRes, permsRes, rpRes] = await Promise.all([
        fetchWithAuth(`${API_BASE_URL}/admin/roles`, {}),
        fetchWithAuth(`${API_BASE_URL}/admin/permissions`, {}),
        fetchWithAuth(`${API_BASE_URL}/admin/role_permissions`, {})
      ]);

      if (rolesRes.ok && permsRes.ok && rpRes.ok) {
        const rolesData: Role[] = await rolesRes.json();
        const permsData: Permission[] = await permsRes.json();
        const rpData: RolePermission[] = await rpRes.json();

        const mappedPerms: MatrixPermission[] = permsData.map(p => ({
          id: p.ID,
          module: p.Module,
          action: p.Name
        }));

        const mappedRoles: MatrixRole[] = rolesData.map(r => ({
          id: r.ID,
          name: r.Name,
          permissions: rpData.filter(rp => rp.RoleID === r.ID).map(rp => rp.PermissionID)
        }));

        setPermissions(mappedPerms);
        setRoles(mappedRoles);
        setOriginalRolePerms(rpData);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const togglePermission = (roleId: string, permissionId: string) => {
    setRoles(prev => prev.map(r => {
      if (r.id !== roleId) return r;
      const hasPerm = r.permissions.includes(permissionId);
      return {
        ...r,
        permissions: hasPerm 
          ? r.permissions.filter(id => id !== permissionId)
          : [...r.permissions, permissionId]
      };
    }));
  };

  const savePermissions = async () => {
    setIsSaving(true);
    try {
      const headers = { "Content-Type": "application/json" };

      // Figure out what to add and what to delete
      const currentRolePerms: RolePermission[] = [];
      roles.forEach(r => {
        r.permissions.forEach(p => {
          currentRolePerms.push({ RoleID: r.id, PermissionID: p });
        });
      });

      const toAdd = currentRolePerms.filter(crp => 
        !originalRolePerms.some(orp => orp.RoleID === crp.RoleID && orp.PermissionID === crp.PermissionID)
      );

      const toDelete = originalRolePerms.filter(orp => 
        !currentRolePerms.some(crp => crp.RoleID === orp.RoleID && crp.PermissionID === orp.PermissionID)
      );

      // Perform API calls sequentially or in Promise.all
      const promises = [];
      for (const a of toAdd) {
        promises.push(fetchWithAuth(`${API_BASE_URL}/admin/permissions/assign`, {
          method: "POST",
          headers,
          body: JSON.stringify({ role_id: a.RoleID, permission_id: a.PermissionID })
        }));
      }
      for (const d of toDelete) {
        promises.push(fetchWithAuth(`${API_BASE_URL}/admin/roles/${d.RoleID}/permissions/${d.PermissionID}`, {
          method: "DELETE",
          headers
        }));
      }

      await Promise.all(promises);

      alert("Permissions saved successfully!");
      fetchData(); // Refresh data
    } catch (err) {
      console.error(err);
      alert("Failed to save permissions");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return <div className="p-8 text-center text-slate-500">Loading Permissions Matrix...</div>;
  }

  const modules = Array.from(new Set(permissions.map(p => p.module)));

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col h-full">
      <div className="p-6 border-b border-slate-200 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-lg font-semibold text-slate-800 flex items-center gap-2">
            <Shield className="w-5 h-5 text-brand" />
            Roles & Permissions Matrix
          </h2>
          <p className="text-sm text-slate-500 mt-1">Configure granular access control for each role.</p>
        </div>
        <Button 
          onClick={savePermissions} 
          disabled={isSaving}
          className="bg-brand hover:bg-brand text-white flex items-center gap-2"
        >
          {isSaving ? "Saving..." : <><Save className="w-4 h-4" /> Save Changes</>}
        </Button>
      </div>

      <div className="flex-1 overflow-auto p-0">
        <table className="w-full text-left border-collapse">
          <thead className="bg-white sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 border-b border-r border-slate-200 font-semibold text-slate-700 w-1/3">
                Module / Permission
              </th>
              {roles.map(role => (
                <th key={role.id} className="p-4 border-b border-r border-slate-200 font-semibold text-slate-700 text-center w-48">
                  {role.name}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {modules.map(moduleName => {
              const modulePerms = permissions.filter(p => p.module === moduleName);
              return (
                <React.Fragment key={moduleName}>
                  <tr className="bg-slate-50">
                    <td colSpan={roles.length + 1} className="p-3 border-b border-slate-200 font-bold text-slate-800 text-sm">
                      {moduleName}
                    </td>
                  </tr>

                  {modulePerms.map(perm => (
                    <tr key={perm.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="p-3 border-b border-r border-slate-200">
                        <div className="font-medium text-slate-700 text-sm">{perm.action}</div>
                      </td>
                      {roles.map(role => {
                        const hasPerm = role.permissions.includes(perm.id);
                        return (
                          <td key={`${role.id}-${perm.id}`} className="p-3 border-b border-r border-slate-200 text-center align-middle">
                            <button
                              onClick={() => togglePermission(role.id, perm.id)}
                              className={`w-8 h-8 rounded flex items-center justify-center mx-auto transition-colors ${
                                hasPerm 
                                  ? "bg-brand-light text-brand hover:bg-indigo-200" 
                                  : "bg-slate-100 text-slate-300 hover:bg-slate-200 hover:text-slate-500"
                              }`}
                              title={hasPerm ? "Revoke permission" : "Grant permission"}
                            >
                              {hasPerm ? <Check className="w-5 h-5" /> : <X className="w-4 h-4" />}
                            </button>
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </React.Fragment>
              );
            })}
            {permissions.length === 0 && (
              <tr>
                <td colSpan={roles.length + 1} className="p-8 text-center text-slate-500">
                  No permissions found in the database.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { apiGet, apiPost, apiPut } from '@/lib/apiClient';
import AISettings from '../settings/AISettings';
import { Activity, Cpu, Zap, ShieldCheck } from 'lucide-react';

interface AgentState {
  id: string;
  name: string;
  role: string;
  status: string;
  loop_count: number;
