interface AgentLog {
  id: string;
  agent_name: string;
  action: string;
  input_data: string;
  output_data: string;
  status: string;
  created_at: string;
}

interface PendingApproval {
  id: string;
  agent_name: string;
  action_type: string;
  payload: string;
  reason: string;
  status: string;
}

interface AIConfig {
  provider: string;
  model: string;
  api_key?: string;
}

export function AgentOrchestrator() {
  const [states, setStates] = useState<AgentState[]>([]);
  const [logs, setLogs] = useState<AgentLog[]>([]);
  const [pending, setPending] = useState<PendingApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'monitoring' | 'providers'>('monitoring');
  const [activeModelName, setActiveModelName] = useState<string>("OpenAI (GPT-4o)");

  const [showDeployModal, setShowDeployModal] = useState(false);
  const [newAgent, setNewAgent] = useState({ name: '', role: '', config: '{}' });

  const fetchStatus = async () => {
    try {
      // For now we just fetch agents. We can keep logs and pending if backend implements them.
      const agentsRes = await apiGet<AgentState[]>('/agents');
      const res = await apiGet<{logs: AgentLog[], pending: PendingApproval[], config: AIConfig}>('/agents/status').catch(() => ({ logs: [], pending: [], config: {} as AIConfig }));
      setStates(agentsRes || []);
      setLogs(res.logs || []);
      setPending(res.pending || []);
      try {
        const saved = localStorage.getItem("septimus_ai_models");
        if (saved) {
          const parsed = JSON.parse(saved);
          const active = parsed.find((m: any) => m.isActive);
          if (active && active.name) setActiveModelName(active.name);
        }
      } catch (e) {}
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    let mounted = true;
    const fetchWrapper = async () => {
      if (mounted) await fetchStatus();
    };
    fetchWrapper();
    const interval = setInterval(fetchWrapper, 3000);
    return () => {
      mounted = false;
      clearInterval(interval);
    };
  }, []);

  const toggleKillSwitch = async (id: string, currentStatus: string) => {
    const newStatus = currentStatus === 'killed' ? 'running' : 'killed';
    await apiPut(`/agents/${id}/status`, { status: newStatus });
    fetchStatus();
  };

  const handleApproval = async (id: string, action: 'approve' | 'reject') => {
    await apiPost(`/agents/approve/${id}`, { action });
    fetchStatus();
  };

  const deployAgent = async () => {
    try {
      const configObj = JSON.parse(newAgent.config);
      await apiPost('/agents', {
        name: newAgent.name,
        role: newAgent.role,
        config: configObj
      });
      setShowDeployModal(false);
      setNewAgent({ name: '', role: '', config: '{}' });
      fetchStatus();
    } catch {
      alert("Invalid JSON config");
    }
  };

  return (
    <div className="flex-1 overflow-y-auto bg-[#f8fafc] p-6 pb-20 min-h-0">
      <div className="max-w-6xl mx-auto space-y-8">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">AI Center</h1>
            <p className="text-slate-500 mt-2">Monitor agents and manage your LLM providers in one place.</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200">
            <button
              onClick={() => setActiveTab('monitoring')}
              className={`px-6 py-2 rounded-lg font-semibold text-sm transition-all ${
                activeTab === 'monitoring' ? 'bg-white text-brand shadow-md' : 'text-slate-500 hover:text-slate-900 hover:bg-white/50'
              }`}
            >
              Monitoring & Control
            </button>
            <button
              onClick={() => setActiveTab('providers')}
              className={`px-6 py-2 rounded-lg font-semibold text-sm transition-all ${
                activeTab === 'providers' ? 'bg-white text-brand shadow-md' : 'text-slate-500 hover:text-slate-900 hover:bg-white/50'
              }`}
            >
              Providers & Models
            </button>
          </div>
        </header>

        {/* ── Live Telemetry Bar ── */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-gradient-to-r from-slate-900 via-indigo-950 to-slate-900 p-6 rounded-2xl text-white shadow-xl border border-slate-800">
          <div className="flex items-center gap-4 border-b md:border-b-0 md:border-r border-slate-800/80 pb-4 md:pb-0 md:pr-4">
