"use client";

import React, { useState, useEffect } from "react";
import { Sparkles, Activity, Cpu, ShieldAlert, Play, Square, Settings2 } from "lucide-react";
import { apiGet, apiPut } from "@/lib/apiClient";
import DeployAgentModal from "./DeployAgentModal";

export default function AIOrchestratorView() {
  const [agents, setAgents] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDeployModalOpen, setIsDeployModalOpen] = useState(false);

  const fetchAgents = async () => {
    try {
      const workspaceId = localStorage.getItem("currentWorkspaceId") || "797ec9d1-e70e-4ca7-a9aa-2d4fed3d879e";
      const res = await apiGet<{data: any[]}>(`/entities?workspace_id=${workspaceId}&type=ai_agent`);
      if (res.data) {
        setAgents(res.data);
      }
    } catch (error) {
      console.error("Failed to fetch agents:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAgents();
  }, []);

  const handleStopAgent = async (agentId: string) => {
    try {
      const workspaceId = localStorage.getItem("currentWorkspaceId") || "797ec9d1-e70e-4ca7-a9aa-2d4fed3d879e";
      await apiPut(`/entities/${agentId}?workspace_id=${workspaceId}`, {
        data: { status: "Idle" }
      });
      fetchAgents();
    } catch (error) {
      console.error("Failed to stop agent:", error);
    }
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-[#f8fafc] text-slate-900 p-8 overflow-y-auto">
      {/* Header */}
      <div className="flex items-center justify-between mb-8 border-b border-slate-200 pb-6">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
            <Sparkles className="w-8 h-8 text-brand" />
            AI Orchestrator
          </h1>
          <p className="text-slate-500 mt-2">
            Monitor, manage, and configure autonomous AI agents across the workspace.
          </p>
        </div>
        <button 
          onClick={() => setIsDeployModalOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-brand hover:bg-brand text-white rounded-md font-medium transition-colors"
        >
          <Play className="w-4 h-4 fill-current" />
          Deploy New Agent
        </button>
      </div>

      {/* Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
        <div className="p-5 bg-white border border-slate-200 rounded-xl">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-slate-500">Active Agents</span>
            <Cpu className="w-4 h-4 text-brand" />
          </div>
          <div className="text-2xl font-bold">{agents.filter(a => a.data?.status === 'Running').length}</div>
        </div>
        <div className="p-5 bg-white border border-slate-200 rounded-xl">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-slate-500">Tasks Executed (24h)</span>
            <Activity className="w-4 h-4 text-green-500" />
          </div>
          <div className="text-2xl font-bold">14</div>
        </div>
        <div className="p-5 bg-white border border-slate-200 rounded-xl">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-slate-500">Errors</span>
            <ShieldAlert className="w-4 h-4 text-red-500" />
          </div>
          <div className="text-2xl font-bold">0</div>
        </div>
        <div className="p-5 bg-white border border-slate-200 rounded-xl">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-slate-500">Compute Used</span>
            <Sparkles className="w-4 h-4 text-yellow-500" />
          </div>
          <div className="text-2xl font-bold">4.2M tokens</div>
        </div>
      </div>

      {/* Active Agents Table */}
      <h2 className="text-xl font-bold mb-4">Deployed Agents</h2>
      <div className="bg-white border border-slate-200 rounded-xl overflow-hidden mb-8">
        <table className="w-full text-left text-sm">
          <thead className="bg-[#f8fafc] border-b border-slate-200 ">
            <tr>
              <th className="px-6 py-3 font-medium text-slate-500">Agent Name</th>
              <th className="px-6 py-3 font-medium text-slate-500">Status</th>
              <th className="px-6 py-3 font-medium text-slate-500">Uptime</th>
              <th className="px-6 py-3 font-medium text-slate-500">Active Tasks</th>
              <th className="px-6 py-3 font-medium text-slate-500 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 ">
            {agents.map((agent) => {
              const data = agent.data || {};
              const status = data.status || "Idle";
              const name = data.name || "Unknown Agent";
              const uptime = data.uptime || "0m";
              const tasks = data.tasks || 0;

              return (
                <tr key={agent.id} className="hover:bg-[#f8fafc] :bg-white/5 transition-colors">
                  <td className="px-6 py-4 font-medium flex items-center gap-2">
                    <BotAvatar name={name} />
                    {name}
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ${
                      status === "Running" 
                        ? "bg-green-100 text-green-700 " 
                        : "bg-slate-100 text-slate-700 "
                    }`}>
                      <span className={`w-1.5 h-1.5 rounded-full ${status === "Running" ? "bg-green-500" : "bg-slate-400"}`} />
                      {status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-slate-500">{uptime}</td>
                  <td className="px-6 py-4">{tasks}</td>
                  <td className="px-6 py-4 text-right">
                    <button 
                      onClick={() => alert(`Settings for ${name} will be available in Phase 4.`)}
                      className="p-2 text-slate-400 hover:text-brand transition-colors" 
                      title="Settings"
                    >
                      <Settings2 className="w-4 h-4" />
                    </button>
                    {status === "Running" && (
                      <button 
                        onClick={() => handleStopAgent(agent.id)}
                        className="p-2 text-slate-400 hover:text-red-500 transition-colors" 
                        title="Stop"
                      >
                        <Square className="w-4 h-4" />
                      </button>
                    )}
                  </td>
                </tr>
              );
            })}
            {agents.length === 0 && !isLoading && (
              <tr>
                <td colSpan={5} className="px-6 py-8 text-center text-slate-500">
                  No agents deployed yet. Click "Deploy New Agent" to get started.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <DeployAgentModal 
        isOpen={isDeployModalOpen}
        onClose={() => setIsDeployModalOpen(false)}
        onDeployed={() => {
          setIsDeployModalOpen(false);
          fetchAgents();
        }}
      />
    </div>
  );
}

function BotAvatar({ name }: { name: string }) {
  return (
    <div className="w-8 h-8 rounded-md bg-brand-light flex items-center justify-center text-brand font-bold text-xs">
      {name.substring(0, 2).toUpperCase()}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { X, Send, Bot, User, Sparkles, Loader2, Maximize2, Minimize2 } from 'lucide-react';
import { apiPost, AI_BASE_URL } from '@/lib/apiClient';

export type AgentType = 'crm' | 'hr' | 'finance' | 'general';

interface AgentChatDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  agentType: AgentType;
  title?: string;
  contextData?: any;
}

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
}

export default function AgentChatDrawer({ isOpen, onClose, agentType, title, contextData }: AgentChatDrawerProps) {
  const getWelcomeMessage = () => {
    if (agentType === 'crm') return 'Hello! I am your CRM Assistant. I can help you draft replies, summarize tickets, or analyze customer data. What do you need?';
    if (agentType === 'hr') return 'Hello! I am your HR Assistant. I can check leave balances, explain company policies, or process requests. How can I help?';
    if (agentType === 'finance') return 'Hello! I am your Finance Assistant. I can summarize expenses, find unpaid invoices, or generate reports. What would you like to do?';
    return 'Hello! How can I help you today?';
  };

  const [messages, setMessages] = useState<Message[]>([{ id: '1', role: 'assistant', content: getWelcomeMessage() }]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  if (!isOpen) return null;

  const handleSend = async (text: string = input) => {
    if (!text.trim()) return;

    const userMessage: Message = { id: Date.now().toString(), role: 'user', content: text };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const workspaceId = localStorage.getItem('currentWorkspaceId') || '797ec9d1-e70e-4ca7-a9aa-2d4fed3d879e';
      const ctx = contextData ? { ...contextData } : {};
      ctx.workspace_id = workspaceId;

      const response = await apiPost<{reply: string}>('/ai/chat', {
        agent_type: agentType,
        message: text,
        context: ctx,
        thread_id: 'default-thread'
      }, AI_BASE_URL);

      setMessages(prev => [...prev, { id: (Date.now() + 1).toString(), role: 'assistant', content: response.reply }]);
    } catch (err) {
      console.error("AI chat error", err);
      setMessages(prev => [...prev, { id: (Date.now() + 1).toString(), role: 'assistant', content: "عذراً، حدث خطأ أثناء الاتصال بالذكاء الاصطناعي." }]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const agentThemeColors = {
    crm: 'text-indigo-500 bg-indigo-50 border-indigo-200',
    hr: 'text-rose-500 bg-rose-50 border-rose-200',
    finance: 'text-emerald-500 bg-emerald-50 border-emerald-200',
    general: 'text-brand bg-brand-light border-brand/20'
  };
  const theme = agentThemeColors[agentType] || agentThemeColors.general;

  return (
    <>
      <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-40 transition-opacity" onClick={onClose} />

      <div className={`fixed top-0 bottom-0 right-0 ${isExpanded ? 'w-full md:w-3/4 lg:w-2/3' : 'w-full md:w-[450px]'} bg-white dark:bg-slate-900 shadow-2xl border-l border-slate-200 dark:border-slate-800 z-50 flex flex-col transition-all duration-300 ease-in-out transform`}>

        {/* Header */}
        <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-800/50">
          <div className="flex items-center gap-3">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center border ${theme}`}>
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <h2 className="font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                {title || 'AI Assistant'}
                <span className="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300">Beta</span>
              </h2>
              <p className="text-xs text-slate-500 font-medium">Powered by Septimus Engine</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsExpanded(!isExpanded)} 
              className="p-2 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg transition-colors hidden md:block"
              title={isExpanded ? 'Minimize' : 'Maximize'}
              aria-label={isExpanded ? 'Minimize' : 'Maximize'}
            >
              {isExpanded ? <Minimize2 className="w-5 h-5" /> : <Maximize2 className="w-5 h-5" />}
            </button>
            <button 
              onClick={onClose} 
              className="p-2 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 hover:text-slate-700 dark:hover:text-slate-200 rounded-lg transition-colors"
              title="Close"
              aria-label="Close"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-white dark:bg-slate-900">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${msg.role === 'user' ? 'bg-slate-800 text-white' : theme.replace('border', '')}`}>
                {msg.role === 'user' ? <User className="w-4 h-4" /> : <Bot className="w-4 h-4" />}
              </div>
              <div className={`max-w-[80%] rounded-2xl p-4 ${msg.role === 'user' ? 'bg-slate-800 text-white rounded-tr-none' : 'bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 text-slate-700 dark:text-slate-300 rounded-tl-none'}`}>
                <p className="text-sm whitespace-pre-wrap leading-relaxed">{msg.content}</p>
              </div>
            </div>
          ))}

          {isTyping && (
            <div className="flex gap-3">
               <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${theme.replace('border', '')}`}>
                <Bot className="w-4 h-4" />
              </div>
              <div className="bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 p-4 rounded-2xl rounded-tl-none flex items-center gap-1.5">
                 <div className="w-2 h-2 rounded-full bg-slate-400 animate-bounce [animation-delay:0ms]" />
                 <div className="w-2 h-2 rounded-full bg-slate-400 animate-bounce [animation-delay:150ms]" />
                 <div className="w-2 h-2 rounded-full bg-slate-400 animate-bounce [animation-delay:300ms]" />
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900">

