"use client";

import { useState, useEffect } from "react";
import { X, Hash } from "lucide-react";
import { apiPut } from "@/lib/apiClient";
import { Channel } from "@/types/chat";

interface ChannelSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  channel: Channel | null;
  onUpdate: () => void;
}

export default function ChannelSettingsModal({ isOpen, onClose, channel, onUpdate }: ChannelSettingsModalProps) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [isPrivate, setIsPrivate] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (channel) {
      setName(channel.Name);
      setDescription(channel.Description || "");
      setIsPrivate(channel.Type === "PRIVATE");
    }
  }, [channel]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!channel) return;

    if (channel.IsSystem) {
      alert("لا يمكن تعديل قنوات النظام الأساسية");
      return;
    }

    setLoading(true);
    try {
      await apiPut(`/channels/${channel.ID}`, {
        name,
        description,
        is_private: isPrivate
      });
      onUpdate();
      onClose();
    } catch (error) {
      alert("حدث خطأ أثناء حفظ الإعدادات");
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen || !channel) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-background border border-border rounded-xl w-[400px] flex flex-col shadow-2xl relative">
        <div className="flex items-center justify-between p-4 border-b border-border">
          <h2 className="text-lg font-semibold text-foreground flex items-center gap-2">
            <Hash size={20} className="text-brand" />
            إعدادات القناة
          </h2>
          <button onClick={onClose} className="p-1 hover:bg-accent rounded-md transition-colors" title="إغلاق">
            <X size={20} className="text-muted-foreground" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-4 space-y-4">
          <div>
            <label className="block text-sm font-medium text-foreground mb-1">اسم القناة</label>
            <input 
              type="text" 
              value={name}
              onChange={(e) => setName(e.target.value)}
              disabled={channel.IsSystem}
              className="w-full bg-background border border-input rounded-md px-3 py-2 text-foreground focus:ring-1 focus:ring-brand focus:border-brand focus:outline-none disabled:opacity-50"
              title="اسم القناة"
              placeholder="اسم القناة"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-foreground mb-1">وصف القناة</label>
            <textarea 
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              disabled={channel.IsSystem}
              className="w-full bg-background border border-input rounded-md px-3 py-2 text-foreground focus:ring-1 focus:ring-brand focus:border-brand focus:outline-none h-24 resize-none disabled:opacity-50"
              title="وصف القناة"
              placeholder="وصف اختياري..."
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-foreground mb-1">خصوصية القناة</label>
            <select
              value={isPrivate ? "private" : "public"}
              onChange={(e) => setIsPrivate(e.target.value === "private")}
              disabled={channel.IsSystem}
              className="w-full bg-background border border-input rounded-md px-3 py-2 text-foreground focus:ring-1 focus:ring-brand focus:border-brand focus:outline-none disabled:opacity-50"
              title="خصوصية القناة"
            >
              <option value="public">عامة (يمكن للجميع الانضمام)</option>
              <option value="private">خاصة (بالدعوة فقط)</option>
            </select>
          </div>

          {channel.IsSystem && (
            <p className="text-xs text-orange-400 bg-orange-400/10 p-2 rounded">
              هذه قناة نظامية، لا يمكنك تعديل اسمها أو وصفها.
            </p>
          )}

          <div className="pt-2">
            <button 
              type="submit" 
              disabled={loading || channel.IsSystem}
              className="w-full bg-brand text-white py-2 rounded-md hover:bg-brand/90 transition-colors disabled:opacity-50 font-medium"
            >
              {loading ? "جاري الحفظ..." : "حفظ التغييرات"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

