"use client";

import { useState, useRef, useEffect } from "react";
import { X, FileText, Play, Pause } from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import MessageInput from "@/components/shared/MessageInput";
import { useThemeStore } from "@/store/useThemeStore";

interface ChatWindowProps {
  chatId: string;
  chatName?: string;
  onClose: () => void;
}

interface Message {
  id: string;
  text: string;
  sender: "me" | "other";
  time: string;
  type?: "text" | "voice" | "file";
  attachmentUrl?: string;
}

const formatTextWithTags = (text: string) => {
  if (!text) return text;
  const regex = /(#[\w\u0600-\u06FF]+|@[\w\u0600-\u06FF.-]+)/g;
  const parts = text.split(regex);

  return parts.map((part, i) => {
    if (part.startsWith('#')) {
      return <span key={i} className="text-brand bg-brand-light px-1 py-0.5 rounded cursor-pointer hover:bg-brand-light font-medium inline-block">{part}</span>;
    }
    if (part.startsWith('@')) {
      return <span key={i} className="text-emerald-600 bg-emerald-50 px-1 py-0.5 rounded cursor-pointer hover:bg-emerald-100 font-medium inline-block">{part}</span>;
    }
    return <span key={i}>{part}</span>;
  });
};

export default function ChatWindow({ chatId, chatName, onClose }: ChatWindowProps) {
  const safeName = chatName || "Chat";
  const { primaryColor } = useThemeStore();
  const [messages, setMessages] = useState<Message[]>([
    { id: "1", text: "مرحباً، كيف يمكنني مساعدتك؟", sender: "other", time: "10:00 AM", type: "text" }
  ]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    let audio: HTMLAudioElement | null = null;
    let timeoutId: NodeJS.Timeout;

    if (playingAudioId) {
      const msg = messages.find(m => m.id === playingAudioId);
      const audioUrl = msg?.attachmentUrl || 'https://actions.google.com/sounds/v1/water/water_drop.ogg';

      if (audioUrl) {
        audio = new Audio(audioUrl);

        // Reset UI when audio finishes naturally
        audio.onended = () => setPlayingAudioId(null);

        audio.play().catch(e => {
          console.error("Audio play failed:", e);
          setPlayingAudioId(null);
        });
      }

      // Fallback timeout only if it's the very short beep
      if (!msg?.attachmentUrl) {
        timeoutId = setTimeout(() => {
          setPlayingAudioId(null);
        }, 3000);
      }
    }

    return () => {
      if (audio) {
        audio.pause();
        audio.currentTime = 0;
        audio.onended = null;
      }
      clearTimeout(timeoutId);
    };
  }, [playingAudioId, messages]);

  const handleSendMessage = (content: string, type: "text" | "voice" | "file" = "text", attachmentUrl?: string) => {
    const newMessage: Message = {
      id: Date.now().toString(),
      text: content,
      type,
      attachmentUrl,
      sender: "me",
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMessage]);

    // Simulate auto-reply
    if (type === "text") {
      setTimeout(() => {
        setMessages(prev => [...prev, {
          id: Date.now().toString() + "1",
          text: "تم استلام رسالتك، سأقوم بالرد قريباً.",
          sender: "other",
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          type: "text"
        }]);
      }, 1500);
    }
  };

  const renderMessageContent = (msg: Message) => {
    if (msg.type === "voice") {
      return (
        <div className="flex items-center gap-2 bg-brand-light text-brand-dark p-2 rounded-lg border border-brand-light min-w-[150px]">
          <button 
            onClick={() => setPlayingAudioId(playingAudioId === msg.id ? null : msg.id)}
            className="w-8 h-8 flex items-center justify-center bg-brand text-white rounded-full hover:bg-brand"
          >
            {playingAudioId === msg.id ? <Pause className="w-4 h-4 fill-current" /> : <Play className="w-4 h-4 fill-current ml-1" />}
          </button>
          <div className="flex-1">
            <div className="h-1.5 bg-indigo-200 rounded-full w-full overflow-hidden">
              <div className={`h-full bg-brand rounded-full ${playingAudioId === msg.id ? 'w-full transition-all duration-[3000ms] ease-linear' : 'w-0'}`} />
            </div>
          </div>
          <span className="text-xs font-mono">{msg.text.match(/\((.*?)\)/)?.[1] || "0:05"}</span>
        </div>
      );
    }

    if (msg.type === "file") {
      const isImage = msg.text.match(/\.(jpeg|jpg|gif|png)$/i);
      if (isImage) {
        return (
          <div className="flex flex-col gap-1">
            <img src={msg.attachmentUrl} alt="attachment" className="rounded-lg max-w-[200px] border border-slate-200" />
            <span className="text-sm">{msg.text}</span>
          </div>
        );
      }
      return (
        <a href={msg.attachmentUrl} target="_blank" rel="noreferrer" className="flex items-center gap-2 bg-slate-50 p-2 rounded-lg border border-slate-200 hover:bg-slate-100 transition-colors">
          <div className="w-8 h-8 flex items-center justify-center bg-brand-light text-brand rounded">
            <FileText className="w-4 h-4" />
          </div>
          <span className="text-sm font-medium underline underline-offset-2">{msg.text}</span>
        </a>
      );
    }

    return <p className="text-sm whitespace-pre-wrap leading-relaxed">{formatTextWithTags(msg.text)}</p>;
  };

  return (
    <div className="w-[340px] h-[480px] bg-white rounded-t-2xl shadow-[0_-5px_25px_-5px_rgba(0,0,0,0.1)] flex flex-col border border-slate-200 overflow-hidden animate-in slide-in-from-bottom-5">
      {/* Header */}
      <div 
        className="h-[60px] px-4 flex items-center justify-between flex-shrink-0 cursor-pointer text-white shadow-sm relative z-20"
        style={{ backgroundColor: primaryColor }}
        onClick={onClose}
      >
        <div className="flex items-center gap-3 overflow-hidden relative z-10">
          <Avatar className="w-8 h-8 border border-white/20 shadow-sm">
            <AvatarFallback className="bg-brand text-white text-xs">{safeName.charAt(0).toUpperCase()}</AvatarFallback>
          </Avatar>
          <div className="flex flex-col">
            <span className="font-semibold text-sm truncate">{safeName}</span>
            <span className="text-[10px] text-indigo-100 flex items-center gap-1">
              <span className="w-1.5 h-1.5 rounded-full bg-green-400"></span> Active Now
            </span>
          </div>
        </div>
        <button onClick={(e) => { e.stopPropagation(); onClose(); }} aria-label="Close Chat" title="Close Chat" className="p-2 hover:bg-white/20 rounded-full transition-colors text-white/90 hover:text-white">
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-3 space-y-4 bg-[#f8fafc]">
        {messages.map((msg) => {
          const isMe = msg.sender === "me";
          return (
            <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
              <div className={`flex flex-col max-w-[80%] ${isMe ? 'items-end' : 'items-start'}`}>
                <div 
                  className={`px-4 py-2.5 max-w-[260px] text-[15px] ${
                    isMe 
                      ? 'text-white rounded-3xl rounded-br-md shadow-sm' 
                      : 'bg-white text-slate-800 border border-slate-100 rounded-3xl rounded-bl-md shadow-sm'
                  }`}
                  style={isMe ? { backgroundColor: primaryColor } : undefined}
                >
                  {renderMessageContent(msg)}
                </div>
                <span className="text-[10px] text-slate-400 mt-1 px-1">{msg.time}</span>
              </div>
            </div>
          );
        })}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <MessageInput 
        channelName={safeName} 
        channelId={chatId}
        variant="compact"
        isDm={true}
        onSend={(text, url, type) => { 
          handleSendMessage(text || "Attachment", (type || "text") as any, url); 
          return true; 
        }} 
      />
    </div>
  );
}

/* eslint-disable @typescript-eslint/no-explicit-any */
"use client";

import React, { useRef, useEffect } from "react";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Button } from "@/components/ui/button";
import { Hash, MessageSquare, Sparkles } from "lucide-react";
import MessageInput from "@/components/shared/MessageInput";
import MessageRow from "@/components/chat/MessageRow";
import ChannelWelcome from "@/components/chat/ChannelWelcome";
import AIRecapModal from "@/components/chat/AIRecapModal";
import LiveDateTime from "@/components/shared/LiveDateTime";
import { useAppStore } from "@/store/useAppStore";
import { fetchWithAuth, API_BASE_URL } from "@/lib/apiClient";
import { Channel } from "@/types";

export default function FullPageChat() {
  const {
    activeChannelId,
    activeDmId,
    currentView,
    channels,
    messages,
    setMessages,
    isThreadsListOpen,
    setIsThreadsListOpen,
    setActiveThread,
    setIsRagSidebarOpen,
    onlineUsers,
    centrifuge,
  } = useAppStore();

  const currentId = (currentView === 'dm' && activeDmId) ? activeDmId : activeChannelId;

  const [isRecapOpen, setIsRecapOpen] = React.useState(false);
  const [recapSummary, setRecapSummary] = React.useState<string | null>(null);
  const [recapCitations, setRecapCitations] = React.useState<string[]>([]);
  const [isRecapLoading, setIsRecapLoading] = React.useState(false);
  const [typingUsers, setTypingUsers] = React.useState<Record<string, boolean>>({});

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Subscribe to channel for typing indicators and chat messages
  useEffect(() => {
    if (!centrifuge || !currentId) return;

    let sub = centrifuge.getSubscription(`channel_${currentId}`);
    if (!sub) {
      sub = centrifuge.newSubscription(`channel_${currentId}`);
      sub.subscribe();
    }

    const handlePublication = (ctx: any) => {
      const msg = ctx.data;
      if (msg.type === 'typing' && msg.user) {
        setTypingUsers(prev => ({
          ...prev,
          [msg.user]: msg.is_typing
        }));
      } else if (msg.type === 'chat_message' || msg.Content || msg.message) {
        const actualMsg = msg.message || msg;
        if (actualMsg.ParentID || actualMsg.parent_id) return;
        const channelId = actualMsg.ChannelID || actualMsg.channel_id;
        if (channelId && String(channelId) !== String(currentId)) return;
        const msgId = String(actualMsg.ID || actualMsg.id || "").trim();
        if (!msgId) return;
        setMessages((prev: any[]) => {
          if (prev.some((p: any) => String(p.ID || p.id || "").trim() === msgId)) return prev;
          return [...prev, actualMsg];
        });
      } else if (msg.type === 'message_updated') {
        const updated = msg.message;
        if (!updated) return;
        const updId = String(updated.ID || updated.id || "").trim();
        setMessages((prev: any[]) => prev.map(p => String(p.ID || p.id || "").trim() === updId ? { ...p, ...updated } : p));
      } else if (msg.type === 'message_deleted') {
        const delId = String(msg.message_id || "").trim();
        if (!delId) return;
        setMessages((prev: any[]) => prev.filter(p => String(p.ID || p.id || "").trim() !== delId));
      }
    };

    sub.on('publication', handlePublication);

    return () => {
      sub?.removeListener('publication', handlePublication);
    };
  }, [centrifuge, currentId, setMessages]);

  const activeChannelRaw = channels.find((c: Channel) => (c.ID || (c as any).id) === currentId);
  const isDm = currentView === 'dm' || activeChannelRaw?.Type === "DM";
  const activeChannel = activeChannelRaw
    ? {
        name: String(activeChannelRaw.Name || (activeChannelRaw as any).name || (isDm ? "محادثة مباشرة" : "قناة عامة")),
        description: String(activeChannelRaw.Description || (isDm ? "رسائل مباشرة ودردشة فورية" : "قناة تواصل ونقاشات")),
      }
    : { name: isDm ? "محادثة مباشرة" : "قناة عامة", description: "" };

  const handleSendMessage = (text: string, attachmentUrl?: string, attachmentType?: string) => {
    if (!currentId) return false;

    fetchWithAuth(`${API_BASE_URL}/channels/${currentId}/messages`, {
      method: "POST",
      body: JSON.stringify({
        content: text,
        AttachmentURL: attachmentUrl,
        AttachmentType: attachmentType
      })
    })
      .then(res => {
        if (res.ok) return res.json();
        throw new Error("Failed to send message");
      })
      .then(newMsg => {
        const msgId = String(newMsg.ID || newMsg.id || "").trim();
        if (!msgId) return;
        setMessages((prev: any[]) => {
          if (prev.some((p: any) => String(p.ID || p.id || "").trim() === msgId)) return prev;
          return [...prev, newMsg];
        });
      })
      .catch(err => console.error(err));
    return true;
  };

  const handleEditMessage = async (id: string, newText: string) => {
    try {
      const res = await fetchWithAuth(`${API_BASE_URL}/messages/${id}`, {
        method: "PUT",
        body: JSON.stringify({ content: newText })
      });
      if (res.ok) {
        const updated = await res.json();
        const updId = String(updated.ID || updated.id || id).trim();
        setMessages((prev: any[]) => prev.map(p => String(p.ID || p.id || "").trim() === updId ? { ...p, ...updated, Content: newText } : p));
      } else {
        alert("فشل تعديل الرسالة، تأكد أنك صاحب الرسالة.");
      }
    } catch (err) {
      console.error(err);
      alert("حدث خطأ أثناء تعديل الرسالة.");
    }
  };

  const handleDeleteMessage = async (id: string) => {
    if (!confirm("هل أنت متأكد من رغبتك في حذف هذه الرسالة؟")) return;
    try {
      const res = await fetchWithAuth(`${API_BASE_URL}/messages/${id}`, {
        method: "DELETE"
      });
      if (res.ok) {
        setMessages((prev: any[]) => prev.filter(p => String(p.ID || p.id || "").trim() !== String(id).trim()));
      } else {
        alert("فشل حذف الرسالة، تأكد أنك صاحب الرسالة.");
      }
    } catch (err) {
      console.error(err);
      alert("حدث خطأ أثناء حذف الرسالة.");
    }
  };

  const handleTriggerRecap = () => {
    if (!activeChannelId) return;
    setIsRecapOpen(true);
    setIsRecapLoading(true);
    fetchWithAuth(`${API_BASE_URL}/chat/recap?channel_id=${activeChannelId}`)
      .then(res => res.json())
      .then(data => {
        setRecapSummary(data.summary || null);
        setRecapCitations(data.citations || []);
        setIsRecapLoading(false);
      })
      .catch((err) => {
        console.error("Recap error:", err);
        setIsRecapLoading(false);
      });
  };

  return (
    <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-slate-50 relative">
      {/* Decorative Background Glows for modern Glassmorphism feel */}
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-brand/5 rounded-full blur-[100px] pointer-events-none -z-10" />
      <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-emerald-500/5 rounded-full blur-[80px] pointer-events-none -z-10" />

      {/* Modern Enterprise Header (Bento Style) */}
      <div className="h-20 bg-white/70 backdrop-blur-md border-b border-white/20 shadow-[0_2px_10px_-4px_rgba(0,0,0,0.05)] px-6 flex items-center justify-between sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-gradient-to-br from-brand to-brand-dark rounded-2xl shadow-lg shadow-brand/20 flex items-center justify-center text-white">
            {isDm ? <MessageSquare className="w-6 h-6" /> : <Hash className="w-6 h-6" />}
          </div>
          <div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
              <span>{activeChannel.name}</span>
              <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-600 border border-emerald-200/60 shadow-sm">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                {Object.values(onlineUsers || {}).filter(Boolean).length || 1} متصل
              </span>
            </h1>
            <p className="text-sm text-slate-500 font-medium">{activeChannel.description || "قناة عامة للتواصل"}</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="hidden lg:flex items-center bg-white border border-slate-200 rounded-full px-3 py-1.5 shadow-sm text-sm text-slate-500">
             <LiveDateTime />
          </div>
          <div className="h-8 w-[1px] bg-slate-200 mx-2 hidden lg:block" />

          <Button variant="ghost" size="sm" className="h-10 px-4 rounded-xl text-slate-600 font-semibold hover:bg-slate-100/80 transition-all" onClick={() => { setIsRagSidebarOpen(true); setActiveThread(null); setIsThreadsListOpen(false); }}>
            <Sparkles className="w-4 h-4 mr-2 text-brand" /> Doc Chat
          </Button>
          <Button variant="ghost" size="sm" className="h-10 px-4 rounded-xl text-slate-600 font-semibold hover:bg-slate-100/80 transition-all" onClick={() => { setIsThreadsListOpen(!isThreadsListOpen); setActiveThread(null); setIsRagSidebarOpen(false); }}>
            <MessageSquare className="w-4 h-4 mr-2" /> Threads
          </Button>
          <Button variant="default" size="sm" className="h-10 px-4 rounded-xl font-bold bg-brand hover:bg-brand-dark shadow-md shadow-brand/20 transition-all" onClick={handleTriggerRecap}>
            <Sparkles className="w-4 h-4 mr-2 text-amber-300 animate-pulse" /> AI Recap
          </Button>
        </div>
      </div>

      {/* Messages Scroll Area */}
      <ScrollArea className="flex-1 px-4 lg:px-8">
        <div className="max-w-5xl mx-auto py-8">
          <ChannelWelcome channelName={activeChannel.name} />

          <div className="flex items-center justify-center my-8">
            <div className="bg-white/60 backdrop-blur-sm border border-slate-200 text-slate-500 text-xs font-bold px-4 py-1.5 rounded-full shadow-sm">
              اليوم
            </div>
          </div>

          <div className="space-y-1">
            {messages.map((rawMsg: unknown, idx: number) => {
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              const msg = rawMsg as Record<string, any>;
              let msgType = "human";
              let author = msg.User ? msg.User.Email : "Unknown";

              if (msg.IsAIGenerated) {
                msgType = "ai";
                author = msg.AIAgentRole || "AI Orchestrator";
              } else if (msg.type === "system") {
                msgType = "system";
                author = "System Event";
              }

              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              const finalMsg: any = {
                ...msg,
                type: msgType,
                author: author,
                time: new Date(msg.CreatedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                text: msg.Content,
                aiProposal: msg.AIProposal,
                entityType: msg.EntityType,
                entityData: msg.EntityID ? { id: msg.EntityID } : undefined
              };

              return (
                <div key={msg.ID || (msg as any).id || `msg-${idx}`} className="transition-all duration-150">
                   <MessageRow 
                     msg={finalMsg}
                     onReplyClick={() => setActiveThread(finalMsg as any)}
                     onEdit={(id, newText) => handleEditMessage(id, newText)}
                     onDelete={(id) => handleDeleteMessage(id)}
                   />
                </div>
              );
            })}
          </div>
          <div ref={messagesEndRef} className="h-8" />
        </div>
      </ScrollArea>

      {/* Floating Input Area (Bento Style) */}
      <div className="p-4 lg:p-6 lg:pt-0 max-w-5xl mx-auto w-full">
        {(() => {
          const activeTypers = Object.entries(typingUsers)
            .filter(([_, isTyping]) => isTyping)
            .map(([u]) => u);
          if (activeTypers.length === 0) return null;
          return (
            <div className="mb-2 px-4 py-1.5 rounded-xl text-xs text-slate-600 font-semibold flex items-center gap-2 animate-pulse bg-white/80 border border-slate-200/80 shadow-sm w-fit">
              <span className="flex gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-brand animate-bounce" style={{ animationDelay: '0ms' }} />
                <span className="w-1.5 h-1.5 rounded-full bg-brand animate-bounce" style={{ animationDelay: '150ms' }} />
                <span className="w-1.5 h-1.5 rounded-full bg-brand animate-bounce" style={{ animationDelay: '300ms' }} />
              </span>
              <span>
                {activeTypers.length === 1
                  ? `${activeTypers[0]} يكتب الآن...`
                  : `${activeTypers.join(" و ")} يكتبون الآن...`}
              </span>
            </div>
          );
        })()}
        <MessageInput
          channelName={activeChannel.name}
          channelId={currentId}
          onSend={handleSendMessage}
        />
      </div>
      <AIRecapModal 
        isOpen={isRecapOpen} 
        onClose={() => setIsRecapOpen(false)} 
        channelName={activeChannel?.name || "general"} 
        summary={recapSummary} 
        citations={recapCitations} 
        isLoading={isRecapLoading} 
      />
    </main>
  );
}

