"use client";

import React, { useEffect, useState } from "react";
import { apiGet } from "@/lib/apiClient";
import { FileText, Search, Filter, Printer, Plus, Trash2, Eye, Building2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import AddInvoiceModal from "./AddInvoiceModal";
import InvoicePrintModal, { SMEInvoiceData } from "./InvoicePrintModal";

interface Entity {
  ID: string;
  EntityType: string;
  Data: SMEInvoiceData;
  CreatedAt: string;
}

export default function InvoicesTable() {
  const [invoices, setInvoices] = useState<Entity[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [selectedPrintInvoice, setSelectedPrintInvoice] = useState<Entity | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState<string>("all");

  const fetchInvoices = async () => {
    try {
      setLoading(true);
      const res = await apiGet("/entities?type=finance_invoice");
      setInvoices(Array.isArray(res) ? res : []);
    } catch (err) {
      console.error("Failed to fetch invoices", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchInvoices();
  }, []);

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذه الفاتورة؟")) return;
    try {
      const { apiDelete } = await import("@/lib/apiClient");
      await apiDelete(`/entities/${id}`);
      fetchInvoices();
    } catch (err) {
      console.error("Failed to delete invoice", err);
      alert("حدث خطأ أثناء الحذف");
    }
  };

  const getStatusColor = (status?: string) => {
    switch (status) {
      case "paid": return "bg-emerald-100 text-emerald-800 border-emerald-200";
      case "pending": return "bg-amber-100 text-amber-800 border-amber-200";
      case "overdue": return "bg-rose-100 text-rose-800 border-rose-200";
      default: return "bg-slate-100 text-slate-700 border-slate-200";
    }
  };

  const getStatusLabel = (status?: string) => {
    switch (status) {
      case "paid": return "مدفوعة بالكامل";
      case "pending": return "قيد الانتظار";
      case "overdue": return "متأخرة";
      default: return status || "معلقة";
    }
  };

  const cycleFilterStatus = () => {
    const statuses = ["all", "paid", "pending", "overdue"];
    const currentIndex = statuses.indexOf(filterStatus);
    setFilterStatus(statuses[(currentIndex + 1) % statuses.length]);
  };

  const filteredInvoices = invoices.filter((inv) => {
    const client = String(inv.Data?.clientName || inv.Data?.client_name || inv.Data?.clientCompany || "");
    const num = String(inv.Data?.invoiceNumber || inv.Data?.invoice_number || inv.ID || "");
    const matchesSearch =
      client.toLowerCase().includes(searchQuery.toLowerCase()) ||
      num.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = filterStatus === "all" || inv.Data?.status === filterStatus;
    return matchesSearch && matchesStatus;
  });

  if (loading && invoices.length === 0) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-brand"></div>
      </div>
    );
  }

  return (
    <div className="h-full overflow-y-auto p-8 relative">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <FileText className="w-6 h-6 text-brand" />
            فواتير الشركات والمؤسسات (SME Invoices)
          </h1>
          <p className="text-slate-500 mt-1">إدارة الفواتير الضريبية، متابعة التحصيل، والطباعة الرسمية المتوافقة مع ZATCA</p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" className="text-slate-600 gap-2 border-slate-200" onClick={cycleFilterStatus}>
            <Filter className="w-4 h-4" />
            {filterStatus === "all" ? "تصفية (الكل)" : `تصفية (${getStatusLabel(filterStatus)})`}
          </Button>
          <Button onClick={() => setIsAddModalOpen(true)} className="bg-brand hover:bg-brand/90 text-white gap-2 shadow-md">
            <Plus className="w-4 h-4" />
            إصدار فاتورة ضريبية جديدة
          </Button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-4 border-b border-slate-200 flex gap-4 bg-slate-50/50">
          <div className="relative flex-1 max-w-md">
            <Search className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              title="بحث في الفواتير"
              aria-label="بحث في الفواتير"
              type="text"
              placeholder="ابحث برقم الفاتورة، اسم العميل، أو الشركة..."
              className="w-full pl-4 pr-10 py-2 bg-white border border-slate-200 rounded-lg text-sm focus:outline-none focus:border-brand focus:ring-1 focus:ring-brand"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-right">
            <thead className="bg-slate-100 text-slate-600 border-b border-slate-200 font-bold text-xs uppercase tracking-wider">
              <tr>
                <th className="px-6 py-4">رقم الفاتورة</th>
                <th className="px-6 py-4">العميل والمؤسسة</th>
                <th className="px-6 py-4">تاريخ الإصدار</th>
                <th className="px-6 py-4">تاريخ الاستحقاق</th>
                <th className="px-6 py-4">الإجمالي المستحق</th>
                <th className="px-6 py-4">الحالة</th>
                <th className="px-6 py-4 text-left">إجراءات والطباعة</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredInvoices.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-slate-500">
                    <FileText className="w-12 h-12 mx-auto text-slate-300 mb-4" />
                    لا توجد فواتير تطابق بحثك حالياً. يمكنك إصدار فاتورة جديدة الآن!
                  </td>
                </tr>
              ) : (
                filteredInvoices.map((inv) => {
                  const num = String(inv.Data?.invoiceNumber || inv.Data?.invoice_number || `INV-${inv.ID.slice(0, 6)}`);
                  const name = String(inv.Data?.clientName || inv.Data?.client_name || "عميل غير محدد");
                  const comp = String(inv.Data?.clientCompany || "");
                  const issue = String(inv.Data?.issueDate || inv.Data?.date || inv.CreatedAt.split("T")[0]);
                  const due = String(inv.Data?.dueDate || inv.Data?.due_date || issue);
                  const total = inv.Data?.amount !== undefined ? Number(inv.Data.amount) : 0;

                  return (
                    <tr key={inv.ID} className="hover:bg-slate-50/80 transition-colors">
                      <td className="px-6 py-4 font-mono font-bold text-slate-900">{num}</td>
                      <td className="px-6 py-4">
                        <p className="font-bold text-slate-900">{name}</p>
                        {comp && <p className="text-xs text-slate-500 font-medium flex items-center gap-1 mt-0.5"><Building2 className="w-3 h-3 text-brand" />{comp}</p>}
                      </td>
                      <td className="px-6 py-4 font-mono text-slate-600">{issue}</td>
                      <td className="px-6 py-4 font-mono text-slate-600">{due}</td>
                      <td className="px-6 py-4 font-mono font-bold text-brand text-base">${total.toFixed(2)}</td>
                      <td className="px-6 py-4">
                        <span className={`px-3 py-1 rounded-full text-xs font-bold border ${getStatusColor(inv.Data?.status)}`}>
                          {getStatusLabel(inv.Data?.status)}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-left">
                        <div className="flex items-center justify-end gap-2">
                          <button
                            onClick={() => setSelectedPrintInvoice(inv)}
                            className="p-2 text-brand bg-brand/10 hover:bg-brand hover:text-white rounded-lg transition-colors flex items-center gap-1 font-semibold text-xs"
                            title="طباعة وتصدير PDF الرسمية"
                            aria-label="طباعة وتصدير PDF الرسمية"
                          >
                            <Printer className="w-4 h-4" />
                            <span>طباعة PDF</span>
                          </button>
                          <button
                            onClick={() => handleDelete(inv.ID)}
                            className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                            title="حذف الفاتورة"
                            aria-label="حذف الفاتورة"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isAddModalOpen && (
        <AddInvoiceModal
          isOpen={isAddModalOpen}
          onClose={() => setIsAddModalOpen(false)}
          onSuccess={fetchInvoices}
        />
      )}

      {selectedPrintInvoice && (
        <InvoicePrintModal
          isOpen={!!selectedPrintInvoice}
          onClose={() => setSelectedPrintInvoice(null)}
          invoiceData={selectedPrintInvoice.Data}
          invoiceId={selectedPrintInvoice.ID}
        />
      )}
    </div>
  );
}

import React from "react";
import { ArrowUpRight, ArrowDownRight, Clock } from "lucide-react";

interface RecentTransactionsProps {
  invoices: any[];
  expenses: any[];
}

export default function RecentTransactions({ invoices, expenses }: RecentTransactionsProps) {
  // Combine, sort, and slice the most recent transactions
  const combined = [
    ...invoices.map(i => ({ 
      id: i.ID, 
      type: 'invoice', 
      title: i.data?.client_name || 'فاتورة مبيعات', 
      amount: Number(i.data?.amount) || 0,
      date: i.data?.issue_date || i.CreatedAt,
      status: i.data?.status || 'pending'
    })),
    ...expenses.map(e => ({ 
      id: e.ID, 
      type: 'expense', 
      title: e.data?.category || 'مصروف عام', 
      amount: Number(e.data?.amount) || 0,
      date: e.data?.date || e.CreatedAt,
      status: 'paid'
    }))
  ];

  const sorted = combined.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 5);

  return (
    <div className="bg-white dark:bg-[#1a1a1a] rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 p-6 h-full transition-colors duration-300">
      <div className="flex justify-between items-center mb-6">
        <h3 className="font-bold text-slate-800 dark:text-slate-100">أحدث المعاملات</h3>
        <button className="text-sm text-brand hover:underline">عرض الكل</button>
      </div>

      <div className="space-y-4">
        {sorted.length === 0 ? (
          <p className="text-center text-slate-500 dark:text-slate-400 py-8">لا توجد معاملات حديثة</p>
        ) : (
          sorted.map((tx, idx) => (
            <div key={idx} className="flex items-center justify-between p-3 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-full ${
                  tx.type === 'invoice' 
                    ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-500/20 dark:text-emerald-400' 
                    : 'bg-red-100 text-red-600 dark:bg-red-500/20 dark:text-red-400'
                }`}>
                  {tx.type === 'invoice' ? <ArrowDownRight className="w-4 h-4" /> : <ArrowUpRight className="w-4 h-4" />}
                </div>
                <div>
                  <p className="font-semibold text-sm text-slate-800 dark:text-slate-200">{tx.title}</p>
                  <p className="text-xs text-slate-500 dark:text-slate-400 flex items-center gap-1 mt-0.5">
                    <Clock className="w-3 h-3" />
                    {tx.date ? new Date(tx.date).toLocaleDateString('en-US', { day: '2-digit', month: 'short', year: 'numeric' }) : "غير محدد"}
                  </p>
                </div>
              </div>

              <div className="text-left">
                <p className={`font-bold text-sm ${
                  tx.type === 'invoice' 
                    ? 'text-emerald-600 dark:text-emerald-400' 
                    : 'text-slate-800 dark:text-slate-200'
                }`}>
                  {tx.type === 'invoice' ? '+' : '-'}${tx.amount.toLocaleString()}
                </p>
                <span className={`text-[10px] px-2 py-0.5 rounded-full mt-1 inline-block ${
                  tx.status === 'paid' 
                    ? 'bg-green-100 text-green-700 dark:bg-green-500/20 dark:text-green-400' 
                    : 'bg-orange-100 text-orange-700 dark:bg-orange-500/20 dark:text-orange-400'
                }`}>
                  {tx.status === 'paid' ? 'مدفوع' : 'معلق'}
                </span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

