                  userLng={userLng}
                  officeLat={officeLat}
                  officeLng={officeLng}
                  radiusMeters={radiusMeters}
                />
              </div>

              {/* Status & Action */}
              <div className="flex flex-col gap-2 p-4 bg-white rounded-md border border-slate-200 ">
                <div className="flex justify-between items-center">
                  <span className="text-sm text-[var(--sb-bg)]/80 [var(--sb-bg)]/70">المسافة عن المقر:</span>
                  <span className="text-sm font-medium text-[var(--sb-bg)] [var(--sb-bg)]">{distance?.toFixed(2)} متر</span>
                </div>

                {isWithinRadius ? (
                  <div className="flex items-center gap-2 text-green-600 mt-2">
                    <CheckCircle2 className="w-4 h-4" />
                    <span className="text-sm font-medium">أنت داخل نطاق الشركة.</span>
                  </div>
                ) : (
                  <div className="flex flex-col gap-2 mt-2">
                    <div className="flex items-center gap-2 text-red-600 ">
                      <XCircle className="w-4 h-4" />
                      <span className="text-sm font-medium">أنت خارج نطاق الشركة!</span>
                    </div>
                    {allowRemote && (
                      <div className="flex items-center gap-2 mt-2 p-2 bg-brand-light rounded border border-brand-light ">
                        <input 
                          type="checkbox" 
                          id="remote-checkin"
                          checked={isRemoteCheckIn}
                          onChange={(e) => setIsRemoteCheckIn(e.target.checked)}
                          className="w-4 h-4 rounded text-brand focus:ring-brand"
                        />
                        <label htmlFor="remote-checkin" className="text-sm text-brand font-medium cursor-pointer">
                          تسجيل حضور عن بعد (Remote Work)
                        </label>
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div className="flex gap-2 justify-end mt-2">
                <Button variant="outline" onClick={getLocation}>
                  تحديث الموقع
                </Button>
                {isCheckedIn ? (
                  <Button 
                    onClick={handleCheckOut}
                    className="bg-red-600 hover:bg-red-700 text-white"
                  >
                    تسجيل الخروج (Check Out)
                  </Button>
                ) : (
                  <Button 
                    onClick={handleCheckIn}
                    disabled={!canCheckIn}
                    className={canCheckIn ? "bg-green-600 hover:bg-green-700 text-white" : "bg-slate-200 text-slate-400 [var(--sb-bg)]/70"}
                  >
                    تسجيل الدخول (Check In)
                  </Button>
                )}
              </div>
            </>
          ) : null}
        </div>
      </DialogContent>
    </Dialog>
  );
}

