// ─── Sub-components ─────────────────────────────────────────────────────

function SidebarDivider() {
  return <div className="sidebar-divider" />;
}

function SidebarSection({
  label,
  children,
  onAdd,
  defaultExpanded = true,
}: {
  label: string;
  children: React.ReactNode;
  onAdd?: () => void;
  defaultExpanded?: boolean;
}) {
  const [isExpanded, setIsExpanded] = React.useState(defaultExpanded);

  return (
    <div className="sidebar-section">
      <div className="sidebar-section-header group">
        <button 
          className="sidebar-section-label" 
          onClick={() => setIsExpanded(!isExpanded)}
        >
          <ChevronDown 
            className={`sidebar-section-chevron transition-transform ${isExpanded ? "" : "-rotate-90"}`} 
          />
          {label}
        </button>
        {onAdd && (
          <button
            onClick={onAdd}
            className="sidebar-section-add"
            aria-label={`Add ${label}`}
          >
            <Plus className="w-4 h-4" />
          </button>
        )}
      </div>
      {isExpanded && <div className="sidebar-section-items">{children}</div>}
    </div>
  );
}

function ChannelItem({
  ch,
  isActive,
  onClick,
  onOpenSettings,
  onOpenMembers,
  onDelete,
}: {
  ch: Channel & { unread?: number };
  isActive: boolean;
  onClick: () => void;
  onOpenSettings?: () => void;
  onOpenMembers?: () => void;
  onDelete?: (id: string) => void;
}) {
  const [showMenu, setShowMenu] = useState(false);

  const handleDelete = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowMenu(false);
    if (!confirm("هل أنت متأكد من حذف هذه القناة؟ لا يمكن التراجع عن هذا الإجراء.")) return;
    try {
      const { apiDelete } = await import('@/lib/apiClient');
      await apiDelete(`/channels/${ch.ID}`);
      onDelete?.(ch.ID);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "خطأ غير معروف";
      alert("حدث خطأ أثناء الحذف: " + msg);
    }
  };

  return (
    <div className="relative group">
      <button
        onClick={onClick}
        className={`sidebar-item w-full ${isActive ? "active" : ""}`}
        aria-current={isActive ? "page" : undefined}
      >
        {ch.Type === "PRIVATE" ? (
          <Lock className="sidebar-item-icon" aria-hidden />
        ) : (
          <Hash className="sidebar-item-icon" aria-hidden />
        )}
        <span className={`sidebar-item-name flex-1 text-right ${ch.unread ? "font-bold" : ""}`}>
          {ch.Name}
        </span>
        {ch.unread && (
          <span className="sidebar-badge" aria-label={`${ch.unread} unread messages`}>
            {ch.unread}
          </span>
        )}
      </button>

      <button
        className="absolute left-2 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 hover:text-white p-1 rounded hover:bg-white/10 transition-all"
        onClick={(e) => {
          e.stopPropagation();
          setShowMenu(!showMenu);
        }}
        title="إعدادات القناة"
      >
        <MoreVertical size={16} />
      </button>

      {showMenu && (
        <div className="absolute left-0 top-10 bg-white border border-gray-200 rounded-lg shadow-xl z-50 py-1 w-40">
          <button 
            className="w-full text-right px-4 py-2.5 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
            onClick={(e) => { e.stopPropagation(); setShowMenu(false); onOpenSettings?.(); }}
          >
            إعدادات القناة
          </button>
          <button 
            className="w-full text-right px-4 py-2.5 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
            onClick={(e) => { e.stopPropagation(); setShowMenu(false); onOpenMembers?.(); }}
          >
            الأعضاء والصلاحيات
          </button>

          {!ch.IsSystem && (
            <button 
              className="w-full text-right px-4 py-2.5 text-sm text-red-500 hover:bg-red-50 border-t border-gray-100 transition-colors"
              onClick={handleDelete}
            >
              حذف القناة
            </button>
          )}
        </div>
      )}
    </div>
  );
}

function DmItem({
  dm,
  isActive,
  onClick,
  onDelete,
}: {
  dm: Channel & { unread?: number };
  isActive: boolean;
  onClick: () => void;
  onDelete?: (id: string) => void;
}) {
  const handleDelete = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm("هل أنت متأكد من حذف هذه المحادثة المباشرة؟ لا يمكن التراجع عن هذا الإجراء.")) return;
    try {
      const { apiDelete } = await import('@/lib/apiClient');
      await apiDelete(`/channels/${dm.ID || (dm as any).id}`);
      onDelete?.(dm.ID || (dm as any).id);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "خطأ غير معروف";
      alert("حدث خطأ أثناء الحذف: " + msg);
    }
  };

  return (
    <div className="relative group">
      <button
        onClick={onClick}
        className={`sidebar-item w-full ${isActive ? "active" : ""}`}
        aria-current={isActive ? "page" : undefined}
      >
        <div className="w-2 h-2 rounded-full bg-green-500 mr-2 shrink-0" />
        <span className={`sidebar-item-name flex-1 text-right truncate ${dm.unread ? "font-bold" : ""}`}>
          {dm.Name || (dm as any).name || "محادثة مباشرة"}
        </span>
        {dm.unread && (
          <span className="sidebar-badge" aria-label={`${dm.unread} unread messages`}>
            {dm.unread}
          </span>
        )}
      </button>

      <button
        className="absolute left-2 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 text-slate-400 hover:text-red-400 p-1 rounded hover:bg-white/10 transition-all"
        onClick={handleDelete}
        title="حذف المحادثة المباشرة"
        aria-label="حذف المحادثة المباشرة"
      >
        <Trash2 size={15} />
      </button>
    </div>
  );
}



// ─── Main Sidebar ─────────────────────────────────────────────────────────



export default function Sidebar() {
  const { t } = useLocalization();
  const { 
    activeChannelId, setActiveChannelId,
    activeDmId, setActiveDmId,
    channels, setChannels,
    onlineUsers,
    currentView, setCurrentView,
    setIsNewChannelModalOpen,
    setIsNewDmModalOpen,
    userStatus, setUserStatus,
    customStatusText, setCustomStatusText
  } = useAppStore();

  const [isStatusMenuOpen, setIsStatusMenuOpen] = useState(false);
  const statusMenuRef = useRef<HTMLDivElement>(null);
  const [avatarUrl, setAvatarUrl] = useState("");

  const [isChannelMembersOpen, setIsChannelMembersOpen] = useState(false);
  const [isChannelSettingsOpen, setIsChannelSettingsOpen] = useState(false);
  const [selectedActionChannel, setSelectedActionChannel] = useState<Channel | null>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (statusMenuRef.current && !statusMenuRef.current.contains(event.target as Node)) {
        setIsStatusMenuOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);

    // Load avatar
    setTimeout(() => {
      const savedAvatar = localStorage.getItem("septimus_avatar");
      if (savedAvatar) setAvatarUrl(savedAvatar);
    }, 0);

    // Listen for avatar updates
    const handleAvatarUpdate = () => {
      const newAvatar = localStorage.getItem("septimus_avatar");
      if (newAvatar) setAvatarUrl(newAvatar);
    };
    window.addEventListener("septimus_avatar_updated", handleAvatarUpdate);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      window.removeEventListener("septimus_avatar_updated", handleAvatarUpdate);
    };
  }, []);

  useEffect(() => {
    const fetchChannels = async () => {
      try {
        const data = await apiGet("/channels");
        setChannels(data as Channel[] || []);
      } catch (err) {
        console.error("Failed to fetch channels", err);
      }
    };
    fetchChannels();
  }, [setChannels]);

  const publicChannels = channels.filter(c => c.Type === "PUBLIC" || c.Type === "PRIVATE");
  const dms = channels.filter(c => c.Type === "DM");

  return (
    <aside className="sidebar" aria-label="Navigation sidebar">
      <ScrollArea className="sidebar-scroll">


        {/* User Status */}
        <div className="relative mb-2" ref={statusMenuRef}>
          <div className="sidebar-user cursor-pointer hover:bg-white/5 transition-colors" onClick={() => setIsStatusMenuOpen(!isStatusMenuOpen)}>
            <div className="relative">
              <Avatar className="sidebar-user-avatar">
                {avatarUrl ? (
                  <AvatarImage src={avatarUrl} alt="Hamza Admin" />
                ) : (
                  <AvatarImage src="https://i.pravatar.cc/40?u=admin" alt="Hamza Admin" />
                )}
                <AvatarFallback className="sidebar-user-fallback">AD</AvatarFallback>
              </Avatar>
              <span className={`sidebar-user-status ${userStatus === 'offline' ? '!bg-gray-400' : userStatus === 'away' ? '!bg-yellow-400' : userStatus === 'busy' ? '!bg-red-500' : '!bg-green-500'}`} aria-label={userStatus} />
            </div>
            <div className="sidebar-user-info">
              <p className="sidebar-user-name">Hamza Admin</p>
              <p className="sidebar-user-sub capitalize truncate w-[100px]">{customStatusText || (userStatus === 'online' ? 'Active' : userStatus === 'busy' ? 'In a meeting' : userStatus)}</p>
            </div>
            <ChevronRight className={`sidebar-user-chevron transition-transform ${isStatusMenuOpen ? 'rotate-90' : ''}`} aria-hidden />
          </div>

          {/* Status Dropdown */}
          {isStatusMenuOpen && (
            <div className="absolute top-full left-0 mt-1 w-full bg-white border border-gray-200 rounded-md shadow-lg z-50 overflow-hidden text-sm">
              <button 
                className="w-full text-left px-3 py-2 flex items-center gap-2 hover:bg-sb-hover transition-colors text-sb-text"
                onClick={() => { setUserStatus("online"); setIsStatusMenuOpen(false); }}
              >
                <span className="w-2.5 h-2.5 rounded-full bg-green-500 shrink-0"></span>
                Active
              </button>
              <button 
                className="w-full text-left px-3 py-2 flex items-center gap-2 hover:bg-sb-hover transition-colors text-sb-text"
                onClick={() => { setUserStatus("away"); setIsStatusMenuOpen(false); }}
              >
                <span className="w-2.5 h-2.5 rounded-full bg-yellow-400 shrink-0"></span>
                Away
              </button>
              <button 
                className="w-full text-left px-3 py-2 flex items-center gap-2 hover:bg-sb-hover transition-colors text-sb-text"
                onClick={() => { setUserStatus("busy"); setIsStatusMenuOpen(false); }}
              >
                <span className="w-2.5 h-2.5 rounded-full bg-red-500 shrink-0"></span>
                In a meeting
              </button>
              <button 
                className="w-full text-left px-3 py-2 flex items-center gap-2 hover:bg-sb-hover transition-colors text-sb-text"
                onClick={() => { setUserStatus("offline"); setIsStatusMenuOpen(false); }}
              >
                <span className="w-2.5 h-2.5 rounded-full bg-gray-400 shrink-0"></span>
                Offline
              </button>
              <div className="border-t border-gray-200 p-2">
                <input 
                  type="text" 
                  placeholder="Set custom status..." 
                  className="w-full text-xs px-2 py-1.5 border border-gray-200 rounded focus:outline-none focus:ring-1 focus:ring-[var(--brand)] bg-transparent text-sb-text placeholder-gray-400"
                  value={customStatusText}
                  onChange={(e) => setCustomStatusText(e.target.value)}
                  onKeyDown={(e) => {
                    if(e.key === 'Enter') {
                      setIsStatusMenuOpen(false);
                    }
                  }}
                  onClick={(e) => e.stopPropagation()}
                />
              </div>
            </div>
          )}
        </div>

        {/* Dashboard / Workspace */}
        <SidebarSection label={t("sidebar.dashboard")}>
          <button className={`sidebar-item ${currentView === 'dashboard' ? "active" : ""}`} onClick={() => setCurrentView('dashboard')}>
            <Home className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.dashboard")}</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* Workspace (Channels) */}
        <SidebarSection label="Channels" onAdd={() => setIsNewChannelModalOpen(true)}>
          <button className={`sidebar-item ${currentView === 'chat' && activeChannelId === '' ? "active" : ""}`} onClick={() => setCurrentView('chat')}>
            <MessageSquare className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Global Chat</span>
          </button>
          {publicChannels.map((ch) => (
            <ChannelItem
              key={ch.ID}
              ch={ch}
              isActive={activeChannelId === ch.ID}
              onClick={() => {
                setActiveChannelId(ch.ID);
                setCurrentView('chat');
              }}
              onOpenSettings={() => {
                setSelectedActionChannel(ch);
                setIsChannelSettingsOpen(true);
              }}
              onOpenMembers={() => {
                setSelectedActionChannel(ch);
                setIsChannelMembersOpen(true);
              }}
              onDelete={(id) => {
                setChannels(channels.filter((c: Channel) => c.ID !== id));
                if (activeChannelId === id) setActiveChannelId('');
              }}
            />
          ))}
        </SidebarSection>

        {/* Direct Messages */}
        <SidebarSection label="Direct Messages" onAdd={() => setIsNewDmModalOpen(true)}>
          {dms.map((dm) => (
            <DmItem
              key={dm.ID || (dm as any).id}
              dm={dm}
              isActive={currentView === 'dm' && activeDmId === (dm.ID || (dm as any).id)}
              onClick={() => {
                setActiveDmId(dm.ID || (dm as any).id);
                setCurrentView('dm');
              }}
              onDelete={(id) => {
                setChannels(channels.filter((c: Channel) => (c.ID || (c as any).id) !== id));
                if (activeDmId === id) setActiveDmId('');
              }}
            />
          ))}
        </SidebarSection>

        <SidebarDivider />

        {/* System */}
        <SidebarSection label={t("sidebar.system")}>
          <button className={`sidebar-item ${currentView === 'plugins' ? "active" : ""}`} onClick={() => setCurrentView('plugins')}>
            <Puzzle className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.plugins")}</span>
          </button>
          <button className={`sidebar-item ${currentView === 'appearance_settings' || currentView === 'roles_settings' || currentView === 'localization_settings' ? "active" : ""}`} onClick={() => setCurrentView('appearance_settings')}>
            <Settings className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.settings")}</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* Analytics & Reports */}
        <SidebarSection label={t("sidebar.analytics")}>
          <button className={`sidebar-item ${currentView === 'reports' ? "active" : ""}`} onClick={() => setCurrentView('reports')}>
            <PieChart className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.reports_center")}</span>
          </button>
          <button className={`sidebar-item ${currentView === 'automations' ? "active" : ""}`} onClick={() => setCurrentView('automations')}>
            <Webhook className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.automations")}</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* Agile & Project Management */}
        <SidebarSection label={t("sidebar.agile_pm")}>
          <button className={`sidebar-item ${currentView === 'kanban' ? "active" : ""}`} onClick={() => setCurrentView('kanban')}>
            <LayoutGrid className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.kanban")}</span>
          </button>
          <button className={`sidebar-item ${currentView === 'backlog' ? "active" : ""}`} onClick={() => setCurrentView('backlog')}>
            <ListTodo className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.backlog")}</span>
          </button>
          <button className={`sidebar-item ${currentView === 'table' ? "active" : ""}`} onClick={() => setCurrentView('table')}>
            <Table className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.table")}</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* Business Modules */}
        <SidebarSection label={t("sidebar.business_suite")}>
          <button className={`sidebar-item ${currentView === 'crm' ? "active" : ""}`} onClick={() => setCurrentView('crm')}>
            <Users className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.crm")}</span>
          </button>
          <button className={`sidebar-item ${currentView === 'hr' ? "active" : ""}`} onClick={() => setCurrentView('hr')}>
            <Database className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.hr")}</span>
          </button>
          <button className={`sidebar-item ${currentView === 'finance' ? "active" : ""}`} onClick={() => setCurrentView('finance')}>
            <CreditCard className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">{t("sidebar.finance")}</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* Knowledge Base */}
        <SidebarSection label="Knowledge Base">
          <button className={`sidebar-item ${currentView === 'workdocs' ? "active" : ""}`} onClick={() => setCurrentView('workdocs')}>
            <FileText className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">WorkDocs</span>
          </button>
          <button className={`sidebar-item ${currentView === 'knowledge_base' ? "active" : ""}`} onClick={() => setCurrentView('knowledge_base')}>
            <Database className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Knowledge Base</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* Automations & Data */}
        <SidebarSection label="Automations & Data">
          <button className={`sidebar-item ${currentView === 'workflows' ? "active" : ""}`} onClick={() => setCurrentView('workflows')}>
            <Zap className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Workflows</span>
          </button>
          <button className={`sidebar-item ${currentView === 'entity_creator' ? "active" : ""}`} onClick={() => setCurrentView('entity_creator')}>
            <Database className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Entity Creator</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* AI AGENTS */}
        <SidebarSection label="AI AGENTS">
          <button className={`sidebar-item ${currentView === 'orchestrator' ? "active" : ""}`} onClick={() => setCurrentView('orchestrator')}>
