        </SidebarSection>

        <SidebarDivider />

        {/* Settings */}
        <SidebarSection label="Settings">
          <button className={`sidebar-item ${currentView === 'admin_dashboard' ? "active" : ""}`} onClick={() => setCurrentView('admin_dashboard')}>
            <Shield className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Admin Dashboard</span>
          </button>
          <button className={`sidebar-item ${currentView === 'roles_settings' ? "active" : ""}`} onClick={() => setCurrentView('roles_settings')}>
            <Users className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Roles & Permissions</span>
          </button>
          <button className={`sidebar-item ${currentView === 'audit_logs' ? "active" : ""}`} onClick={() => setCurrentView('audit_logs')}>
            <Shield className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Audit Logs</span>
          </button>
          <button className="sidebar-item" onClick={() => setCurrentView('webhooks_settings')}>
            <Webhook className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">Webhooks</span>
          </button>
          <button className="sidebar-item" onClick={() => setCurrentView('apikeys_settings')}>
            <Key className="sidebar-item-icon" aria-hidden />
            <span className="sidebar-item-name">API Keys</span>
          </button>
        </SidebarSection>

        <SidebarDivider />

        {/* Extensions */}
        <SidebarSection label="Extensions">
          <Link href="/plugins" className="sidebar-item block w-full text-left">
            <div className="flex items-center w-full">
              <Puzzle className="sidebar-item-icon" aria-hidden />
              <span className="sidebar-item-name">Enterprise Plugins</span>
