import React, { useState, useEffect } from "react";
import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import TaskCard from "./TaskCard";
import NewTaskModal from "./NewTaskModal";
import { DragDropContext, Droppable, DropResult } from "@hello-pangea/dnd";
import { useAppStore } from "@/store/useAppStore";
import { apiGet, apiPost } from "@/lib/apiClient";
import { Task } from "@/types";

export default function KanbanBoard() {
  const { tasks, setTasks, projectId, setProjectId } = useAppStore();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [sprints, setSprints] = useState<any[]>([]);
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);

  // Constants for our columns based on backend State Machine
  const columns = [
    { id: "todo", title: "To Do" },
    { id: "in_progress", title: "In Progress" },
    { id: "review", title: "Review" },
    { id: "done", title: "Done" },
  ];

  const fetchTasksAndSprints = async (pid: string) => {
    try {
      const [tasksData, sprintsData] = await Promise.all([
        apiGet<{tasks: Task[]}>(`/tasks?project_id=${pid}`),
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        apiGet<any[]>(`/sprints?project_id=${pid}`)
      ]);

      setTasks(tasksData.tasks || []);
      setSprints(sprintsData || []);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const fetchOrCreateProject = async () => {
      try {
        // Try fetching first project
        try {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const data = await apiGet<any[]>("/projects");
          if (data && data.length > 0) {
            setProjectId(data[0].ID);
            fetchTasksAndSprints(data[0].ID);
            return;
          }
        } catch (e) {
          console.warn("Failed to fetch projects, will create default", e);
        }

        // If no project, create a default one
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const newProj = await apiPost<any>("/projects", { name: "Default Project", settings: {} });
        setProjectId(newProj.ID);
        fetchTasksAndSprints(newProj.ID);
      } finally {
        setIsLoading(false);
      }
    };

    fetchOrCreateProject();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [setProjectId, setTasks]);

  const handleTransition = async (taskId: string, newStatus: string) => {
    try {
      await apiPost(`/tasks/${taskId}/transition`, { status: newStatus });
      // The local state update happens before this API call via onDragEnd
    } catch (err: any) {
      console.error("Transition error", err);
      alert(`Transition failed: ${err.message}`);
      // Re-fetch to revert optimistic update
      fetchTasksAndSprints(projectId);
    }
  };

  const onDragEnd = (result: DropResult) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;
    if (destination.droppableId === source.droppableId && destination.index === source.index) return;

    // Optimistically update the UI in global store
    const newStatus = destination.droppableId;
    setTasks((prevTasks: Task[]) => prevTasks.map((t: Task) => t.ID === draggableId ? { ...t, Status: newStatus } : t));

    // Send API request
    handleTransition(draggableId, newStatus);
  };

  if (isLoading) {
    return <div className="flex-1 flex items-center justify-center text-slate-400">Loading Kanban Board...</div>;
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const activeSprint = sprints.find((s) => s.Status === "active") as any;
  const sprintTasks = activeSprint ? tasks.filter((t) => t.SprintID === activeSprint.ID) : [];

  const selectedTask = tasks.find(t => t.ID === selectedTaskId);

  return (
    <div className="flex-1 flex flex-col h-full bg-white text-slate-900 overflow-hidden relative">
      {/* Kanban Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-200">
        <div className="flex flex-col space-y-1">
          <h2 className="text-xl font-bold text-gray-800">Board</h2>
          {activeSprint ? (
             <span className="text-sm font-medium text-slate-500">Active Sprint: {activeSprint.Name}</span>
          ) : (
             <span className="text-sm font-medium text-amber-600">No active sprint. Please start a sprint from the Backlog view.</span>
          )}
        </div>
        <Button onClick={() => setIsModalOpen(true)} className="gap-2">
          <Plus className="w-4 h-4" /> New Task
        </Button>
      </div>

      {/* Board Area */}
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="flex-1 overflow-x-auto overflow-y-hidden p-6">
          <div className="flex h-full items-start space-x-6 min-w-max">
            {columns.map((col) => {
              const columnTasks = sprintTasks.filter((t) => t.Status === col.id);
              return (
                <div key={col.id} className="w-80 flex flex-col h-full max-h-full bg-[#f8fafc]/50 rounded-xl border border-slate-100">
                  <div className="flex items-center justify-between mb-2 px-3 py-3 border-b border-slate-100">
                    <h3 className="font-semibold text-slate-800 flex items-center gap-2">
                      <div className={`w-2 h-2 rounded-full ${
                        col.id === 'todo' ? 'bg-slate-400' :
                        col.id === 'in_progress' ? 'bg-[#dfb2e5]' :
                        col.id === 'review' ? 'bg-amber-400' : 'bg-emerald-400'
                      }`} />
                      {col.title}
                    </h3>
                    <span className="text-xs font-semibold bg-slate-100 text-slate-500 py-1 px-2 rounded-full">
                      {columnTasks.length}
                    </span>
                  </div>

                  {/* Column Content */}
                  <Droppable droppableId={col.id}>
                    {(provided, snapshot) => (
                      <div 
                        ref={provided.innerRef}
                        {...provided.droppableProps}
                        className={`flex-1 overflow-y-auto px-2 custom-scrollbar pb-4 transition-colors ${snapshot.isDraggingOver ? 'bg-slate-100/80 rounded-b-xl' : ''}`}
                      >
                        {columnTasks.length === 0 && !snapshot.isDraggingOver ? (
                          <div className="h-24 border-2 border-dashed border-slate-200 rounded-xl flex items-center justify-center text-sm text-slate-400">
                            No tasks
                          </div>
                        ) : (
                          columnTasks.map((task, index) => (
                            <div key={task.ID} onClick={() => setSelectedTaskId(task.ID)}>
                              <TaskCard task={task} index={index} onTransition={handleTransition} />
                            </div>
                          ))
                        )}
                        {provided.placeholder}
                      </div>
                    )}
                  </Droppable>
                </div>
              );
            })}
          </div>
        </div>
      </DragDropContext>

      {/* Task Details Right Panel (Slide Over) */}
      {selectedTask && (
        <div className="absolute top-0 right-0 h-full w-[400px] bg-white shadow-2xl border-l border-slate-200 z-50 flex flex-col animate-in slide-in-from-right duration-200">
          <div className="flex items-center justify-between p-4 border-b border-slate-100">
            <div className="flex items-center gap-2">
              <span className="text-xs font-mono text-slate-400">TASK-{selectedTask.ID.substring(0,4)}</span>
            </div>
            <button 
              onClick={() => setSelectedTaskId(null)}
              className="p-2 hover:bg-slate-100 rounded-md text-slate-500 transition-colors"
              title="Close Task"
              aria-label="Close Task"
            >
              <svg width="15" height="15" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12.8536 2.85355C13.0488 2.65829 13.0488 2.34171 12.8536 2.14645C12.6583 1.95118 12.3417 1.95118 12.1464 2.14645L7.5 6.79289L2.85355 2.14645C2.65829 1.95118 2.34171 1.95118 2.14645 2.14645C1.95118 2.34171 1.95118 2.65829 2.14645 2.85355L6.79289 7.5L2.14645 12.1464C1.95118 12.3417 1.95118 12.6583 2.14645 12.8536C2.34171 13.0488 2.65829 13.0488 2.85355 12.8536L7.5 8.20711L12.1464 12.8536C12.3417 13.0488 12.6583 13.0488 12.8536 12.8536C13.0488 12.6583 13.0488 12.3417 12.8536 12.1464L8.20711 7.5L12.8536 2.85355Z" fill="currentColor" fillRule="evenodd" clipRule="evenodd"></path>
              </svg>
            </button>
          </div>
          <div className="p-6 overflow-y-auto flex-1">
            <h2 className="text-2xl font-bold text-slate-900 mb-6 leading-tight">{selectedTask.Title}</h2>

            <div className="space-y-6">
              {/* Properties */}
              <div className="grid grid-cols-3 gap-y-4 text-sm">
                <div className="text-slate-500">Status</div>
                <div className="col-span-2">
                  <span className="px-2 py-1 bg-slate-100 rounded-md font-medium text-slate-700 capitalize">
                    {selectedTask.Status.replace('_', ' ')}
                  </span>
                </div>

                <div className="text-slate-500">Assignee</div>
                <div className="col-span-2 flex items-center gap-2">
                  <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center text-xs font-bold text-slate-600">
                    UN
                  </div>
                  <span className="text-slate-700 font-medium">Unassigned</span>
                </div>

                <div className="text-slate-500">Priority</div>
                <div className="col-span-2">
                  {selectedTask.Priority > 0 ? (
                    <span className="text-red-600 font-medium flex items-center gap-1">
                      <svg width="15" height="15" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7.5 1V14M7.5 1L3.5 5M7.5 1L11.5 5" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round"/></svg>
                      High
                    </span>
                  ) : (
                    <span className="text-slate-500 flex items-center gap-1">
                      <svg width="15" height="15" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M2 7.5H13" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round"/></svg>
                      Normal
                    </span>
                  )}
                </div>
              </div>

              <div className="w-full h-px bg-slate-100" />

              {/* Description */}
              <div>
                <h3 className="text-sm font-semibold text-slate-900 mb-2">Description</h3>
                <p className="text-slate-600 text-sm whitespace-pre-wrap leading-relaxed">
                  {selectedTask.Description || "No description provided."}
                </p>
              </div>
            </div>
          </div>

          <div className="p-4 border-t border-slate-100 bg-[#f8fafc]">
            <button className="w-full py-2 bg-brand text-white rounded-md font-medium hover:bg-brand transition-colors">
              Save Changes
            </button>
          </div>
        </div>
      )}

      <NewTaskModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        projectId={projectId} 
        onTaskCreated={() => fetchTasksAndSprints(projectId)} 
      />
    </div>
  );
}

import React from 'react';
import { Sparkles, X, Wand2, CheckSquare, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Task, AIProposal } from '@/types';

interface AIAutoPlanModalProps {
  isOpen: boolean;
  proposal: AIProposal | null;
  isAssigning: boolean;
  onClose: () => void;
  onAccept: () => void;
  priorities: { label: string, value: number, badge: string }[];
}

export function AIAutoPlanModal({
  isOpen,
  proposal,
  isAssigning,
  onClose,
  onAccept,
  priorities
}: AIAutoPlanModalProps) {
  if (!isOpen || !proposal) return null;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl border border-brand-light shadow-2xl max-w-2xl w-full overflow-hidden flex flex-col max-h-[85vh]">
        <div className="p-6 bg-gradient-to-r from-purple-600 via-indigo-600 to-indigo-700 text-white flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-white/10 backdrop-blur-md rounded-xl">
              <Sparkles className="w-6 h-6 text-purple-200 animate-pulse" />
            </div>
            <div>
              <h3 className="text-lg font-black tracking-tight">AI Agile Co-Pilot Proposal</h3>
              <p className="text-xs text-purple-200 font-medium">Auto-planned sprint increment for {proposal.targetSprint.Name}</p>
            </div>
          </div>
          <button onClick={onClose} title="Close AI Proposal" aria-label="Close AI Proposal" className="text-white/70 hover:text-white p-1 rounded-lg hover:bg-white/10">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 overflow-y-auto space-y-6 flex-1">
          <div className="bg-brand-light border border-brand-light rounded-xl p-4 text-xs text-brand-dark space-y-1">
            <div className="font-bold flex items-center gap-1.5 text-purple-950 text-sm">
              <Wand2 className="w-4 h-4 text-brand" /> AI Strategy Rationale:
            </div>
            <p className="leading-relaxed text-brand-dark font-medium">{proposal.rationale}</p>
          </div>

          <div>
            <div className="flex justify-between items-center mb-3">
              <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Proposed Work Items ({proposal.selectedTasks.length})</span>
              <span className="text-xs font-bold text-brand bg-brand-light px-2.5 py-1 rounded-full border border-brand-light">
                Total Load: {proposal.selectedTasks.reduce((acc, t) => acc + (t.StoryPoints || 0), 0)} / 30 pts
              </span>
            </div>

            <div className="space-y-2 max-h-60 overflow-y-auto pr-1">
              {proposal.selectedTasks.map(task => {
                const prio = priorities.find(p => p.value === (task.Priority || 0)) || priorities[3];
                return (
                  <div key={task.ID} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-200/80">
                    <div className="flex items-center gap-3">
                      <CheckSquare className="w-4 h-4 text-brand" />
                      <span className="text-xs font-mono font-bold text-slate-400">T-{task.ID.substring(0,4)}</span>
                      <span className="text-sm font-semibold text-slate-800">{task.Title}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className={`text-[10px] px-2 py-0.5 rounded font-bold border ${prio.badge}`}>{prio.label}</span>
                      <span className="text-xs font-bold bg-white px-2 py-0.5 rounded border border-slate-200 text-slate-700">{task.StoryPoints || 0} pts</span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-3">
          <Button variant="outline" onClick={onClose} disabled={isAssigning} className="font-semibold text-xs">
            Discard Proposal
          </Button>
          <Button onClick={onAccept} disabled={isAssigning} className="bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 text-white font-bold text-xs shadow-md">
            {isAssigning ? "Assigning Tasks..." : `Accept & Assign (${proposal.selectedTasks.length} Tasks)`} <ArrowRight className="w-4 h-4 ml-1.5" />
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Download, Users, Clock, AlertTriangle, Building2, MapPin } from 'lucide-react';
import { apiGet } from '@/lib/apiClient';
import { useThemeStore } from '@/store/useThemeStore';
import { useLocalization } from '@/contexts/LocalizationContext';

interface AttendanceLog {
  ID: string;
  UserID: string;
  OfficeID: string;
  CheckInTime: string;
  CheckOutTime?: string;
  Status: string;
  User?: {
    Name: string;
    Email: string;
  };
  Office?: {
    Name: string;
  };
}

export default function AttendanceReport() {
  const { t, language } = useLocalization();
  const [logs, setLogs] = useState<AttendanceLog[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const primaryColor = useThemeStore((state) => state.primaryColor);
  const primaryLight = `${primaryColor}1A`;

  const mockAttendanceData = [
    { name: t("reports.days.sun", 'الأحد'), hours: 8, expected: 8 },
    { name: t("reports.days.mon", 'الإثنين'), hours: 8.5, expected: 8 },
    { name: t("reports.days.tue", 'الثلاثاء'), hours: 7.5, expected: 8 },
    { name: t("reports.days.wed", 'الأربعاء'), hours: 9, expected: 8 },
    { name: t("reports.days.thu", 'الخميس'), hours: 8, expected: 8 },
  ];

  const mockStatusData = [
    { name: t("reports.status.onTime", 'حضور بالوقت'), value: 65, color: '#10b981' }, // Green
    { name: t("reports.status.late", 'تأخير'), value: 15, color: '#f59e0b' },      // Yellow
    { name: t("reports.status.remote", 'عمل عن بعد'), value: 15, color: '#3b82f6' }, // Blue
    { name: t("reports.status.absent", 'غياب'), value: 5, color: '#ef4444' },        // Red
  ];

  // Compute stats from logs
  const calculateStats = () => {
    let present = 0, late = 0, absent = 0, remote = 0;
    let totalHours = 0;

    logs.forEach(log => {
      if (log.Status === 'present') present++;
      else if (log.Status === 'late') late++;
      else if (log.Status === 'absent') absent++;
      else remote++;

      if (log.CheckOutTime && log.CheckInTime) {
        const inTime = new Date(log.CheckInTime);
        const outTime = new Date(log.CheckOutTime);
        totalHours += (outTime.getTime() - inTime.getTime()) / (1000 * 60 * 60);
      }
    });

    const totalLogs = logs.length || 1;
    const avgHours = totalHours / totalLogs;

    return {
      statusData: [
        { name: t("reports.status.onTime", 'حضور بالوقت'), value: present, color: '#10b981' },
        { name: t("reports.status.late", 'تأخير'), value: late, color: '#f59e0b' },
        { name: t("reports.status.remote", 'عمل عن بعد'), value: remote, color: '#3b82f6' },
        { name: t("reports.status.absent", 'غياب'), value: absent, color: '#ef4444' },
      ].filter(item => item.value > 0), // hide empty statuses
      avgHours: avgHours.toFixed(1),
      presentPercentage: Math.round(((present + late) / totalLogs) * 100)
    };
  };

  const { statusData, avgHours, presentPercentage } = calculateStats();

  // Provide fallback mock data if empty
  const activeStatusData = statusData.length > 0 ? statusData : mockStatusData;

  const fetchLogs = async () => {
    try {
      const data = await apiGet('/attendance/logs') as unknown as AttendanceLog[];
      setLogs(data || []);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    queueMicrotask(() => { void fetchLogs(); });
  }, []);

  return (
    <div className="flex flex-col gap-6">

      {/* Top Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title={t("reports.totalEmployees", "إجمالي الموظفين")} value="42" icon={<Users className="w-5 h-5" style={{ color: primaryColor }} />} />
        <StatCard title={t("reports.avgHours", "متوسط ساعات العمل")} value={`${avgHours} ${t("reports.hoursPerDay", "س/يوم")}`} icon={<Clock className="w-5 h-5" style={{ color: primaryColor }} />} />
        <StatCard title={t("reports.attendanceLogs", "سجلات الحضور (الكل)")} value={logs.length.toString()} icon={<AlertTriangle className="w-5 h-5" style={{ color: primaryColor }} />} />
        <StatCard title={t("reports.presenceRate", "نسبة التواجد")} value={`${presentPercentage}%`} icon={<Building2 className="w-5 h-5" style={{ color: primaryColor }} />} />
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Weekly Hours Bar Chart */}
        <div className="col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-semibold mb-6 text-slate-800 ">{t("reports.totalHoursWeek", "إجمالي ساعات العمل (هذا الأسبوع)")}</h3>
          <div className="h-72 w-full" dir="ltr">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={mockAttendanceData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <YAxis axisLine={false} tickLine={false} />
                <Tooltip cursor={{ fill: 'rgba(0,0,0,0.05)' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                <Legend />
                <Bar dataKey="expected" name={t("reports.expectedHours", "الساعات المتوقعة")} fill="#e2e8f0" radius={[4, 4, 0, 0]} />
                <Bar dataKey="hours" name={t("reports.actualHours", "الساعات الفعلية")} fill={primaryColor} radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Status Pie Chart */}
        <div className="col-span-1 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-semibold mb-6 text-slate-800 ">{t("reports.statusDistribution", "توزيع الحالات (هذا الشهر)")}</h3>
          <div className="h-64 w-full" dir="ltr">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={activeStatusData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {activeStatusData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          {/* Custom Legend */}
          <div className="flex flex-wrap justify-center gap-4 mt-4">
            {activeStatusData.map((item, i) => (
              <div key={i} className="flex items-center gap-2 text-sm text-slate-600 ">
                <span className="w-3 h-3 rounded-full inline-block" ref={(el) => { if (el) el.style.backgroundColor = item.color; }} />
                {item.name} ({item.value})
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Data Table */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center">
          <h3 className="text-lg font-semibold text-slate-800 ">{t("reports.dailyLog", "السجل اليومي (Live)")}</h3>
          <button className="flex items-center gap-2 text-sm bg-slate-100 hover:bg-slate-200 text-slate-700 px-3 py-1.5 rounded-md transition-colors">
            <Download className="w-4 h-4" />
            {t("common.exportCsv", "تصدير CSV")}
          </button>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-start">
            <thead className="bg-[#f8fafc] text-slate-500 ">
              <tr>
                <th className="px-6 py-3 font-medium text-start">{t("reports.employee", "الموظف")}</th>
                <th className="px-6 py-3 font-medium text-start">{t("reports.dateIn", "التاريخ / الدخول")}</th>
                <th className="px-6 py-3 font-medium text-start">{t("reports.out", "الخروج")}</th>
                <th className="px-6 py-3 font-medium text-start">{t("reports.statusHeader", "الحالة")}</th>
                <th className="px-6 py-3 font-medium text-start">{t("reports.location", "المقر")}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 text-slate-700 ">
              {logs.map((row) => (
                <tr key={row.ID} className="hover:bg-[#f8fafc] transition-colors">
                  <td className="px-6 py-4 font-medium text-slate-900 ">{row.User?.Name || t("reports.unknownUser", "مستخدم غير معروف")}</td>
                  <td className="px-6 py-4">{new Date(row.CheckInTime).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US')}</td>
                  <td className="px-6 py-4">{row.CheckOutTime ? new Date(row.CheckOutTime).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US') : '-'}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-medium
                      ${row.Status === 'present' ? 'bg-green-100 text-green-700 ' : 'bg-slate-100 text-slate-700 '}
                    `}>
                      {row.Status}
                    </span>
                  </td>
                  <td className="px-6 py-4">{row.Office?.Name || t("reports.headquarters", "المقر الرئيسي")}</td>
                </tr>
              ))}
              {logs.length === 0 && !isLoading && (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-slate-500">{t("reports.noLogs", "لا توجد سجلات حضور حتى الآن.")}</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

