"use client";

import React, { useState, useEffect, useCallback } from "react";
import { Webhook, Plus, Save, Trash2, Power, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { fetchWithAuth,     API_BASE_URL } from '@/lib/apiClient';

export default function WebhooksSettings() {
  const [hooks, setHooks] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAdding, setIsAdding] = useState(false);
  const [newHookUrl, setNewHookUrl] = useState("");
  const [newHookSecret, setNewHookSecret] = useState("");
  const [newHookEvents, setNewHookEvents] = useState("events.tasks.created");

  const fetchWebhooks = async () => {
    try {
            const res = await fetchWithAuth(`${API_BASE_URL}/workspaces/me/webhooks`);
      if (res.ok) {
        const data = await res.json();
        setHooks(data || []);
      }
    } catch (err) {
      console.error("Failed to fetch webhooks:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const loadData = async () => {
      await fetchWebhooks();
    };
    loadData();
  }, []);

  const handleAddWebhook = async () => {
    if (!newHookUrl) return;
    try {
            const res = await fetchWithAuth(`${API_BASE_URL}/workspaces/me/webhooks`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",

        },
        body: JSON.stringify({
          target_url: newHookUrl,
          events: newHookEvents.split(",").map(e => e.trim()),
          secret: newHookSecret,
        })
      });
      if (res.ok) {
        setIsAdding(false);
        setNewHookUrl("");
        setNewHookSecret("");
        setNewHookEvents("events.tasks.created");
        fetchWebhooks();
      }
    } catch (err) {
      console.error("Failed to add webhook:", err);
    }
  };

  const handleDeleteWebhook = async (id: string) => {
    try {
            const res = await fetchWithAuth(`${API_BASE_URL}/workspaces/me/webhooks/${id}`, {
        method: "DELETE",

      });
      if (res.ok) {
        fetchWebhooks();
      }
    } catch (err) {
      console.error("Failed to delete webhook:", err);
    }
  };

  return (
    <div className="w-full h-full p-8 overflow-y-auto bg-[#f8fafc]">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center gap-3 mb-2">
          <div className="p-2 bg-brand-light text-brand rounded-lg">
            <Webhook className="w-6 h-6" />
          </div>
          <h1 className="text-3xl font-bold text-slate-800">Webhooks</h1>
        </div>
        <p className="text-slate-500 mb-8 ml-11">
          Subscribe to workspace events to integrate with external systems.
        </p>

        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden mb-8">
          <div className="p-6 border-b border-slate-200 flex justify-between items-center">
            <h2 className="text-lg font-semibold text-slate-800">Endpoints</h2>
            <Button className="bg-brand hover:bg-brand text-white" onClick={() => setIsAdding(true)}>
              <Plus className="w-4 h-4 mr-2" /> Add Endpoint
            </Button>
          </div>

          {isAdding && (
            <div className="p-6 border-b border-slate-200 bg-slate-50">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-semibold text-slate-700">Add New Webhook</h3>
                <Button variant="ghost" size="sm" onClick={() => setIsAdding(false)}>
                  <X className="w-4 h-4" />
                </Button>
              </div>
              <div className="grid gap-4 mb-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Target URL</label>
                  <input 
                    type="text" 
                    className="w-full p-2 border border-slate-300 rounded-md" 
                    placeholder="https://webhook.site/..." 
                    value={newHookUrl} 
                    onChange={e => setNewHookUrl(e.target.value)} 
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Events (comma-separated)</label>
                  <input 
                    type="text" 
                    className="w-full p-2 border border-slate-300 rounded-md" 
                    placeholder="events.tasks.created" 
                    value={newHookEvents} 
                    onChange={e => setNewHookEvents(e.target.value)} 
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Secret (Optional for HMAC signature)</label>
                  <input 
                    type="password" 
                    className="w-full p-2 border border-slate-300 rounded-md" 
                    placeholder="Your secret key" 
                    value={newHookSecret} 
                    onChange={e => setNewHookSecret(e.target.value)} 
                  />
                </div>
              </div>
              <div className="flex justify-end">
                <Button onClick={handleAddWebhook} className="bg-green-600 hover:bg-green-700 text-white">
                  <Save className="w-4 h-4 mr-2" /> Save Webhook
                </Button>
              </div>
            </div>
          )}

          <div className="divide-y divide-slate-100">
            {loading ? (
              <div className="p-8 text-center text-slate-500">Loading webhooks...</div>
            ) : hooks.length === 0 ? (
              <div className="p-8 text-center text-slate-500">No webhooks configured yet.</div>
            ) : (
              hooks.map(hook => (
                <div key={hook.ID} className="p-6 flex flex-col sm:flex-row sm:items-center justify-between gap-4 hover:bg-[#f8fafc] transition-colors">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-1">
                      <span className={`w-2 h-2 rounded-full ${hook.IsActive ? 'bg-green-500' : 'bg-slate-300'}`}></span>
                      <h3 className="font-semibold text-slate-800 font-mono text-sm">{hook.TargetURL}</h3>
                    </div>
                    <div className="flex items-center gap-2 mt-2 ml-5">
                      {hook.Events && hook.Events.map((ev: string) => (
                        <span key={ev} className="text-xs bg-slate-100 text-slate-600 px-2 py-1 rounded font-medium border border-slate-200">
                          {ev}
                        </span>
                      ))}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button variant="outline" size="sm" className="text-slate-600">
                      <Power className="w-4 h-4 mr-1" /> {hook.IsActive ? "Disable" : "Enable"}
                    </Button>
                    <Button variant="outline" size="sm" className="text-red-600 hover:text-red-700 hover:bg-red-50" onClick={() => handleDeleteWebhook(hook.ID)}>
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

